    eternalRev5: 'ਸਾਰੇ ਸਦੀਵੀ ਲਈ ਪੈਸਿਵ ਆਮਦਨੀ',
    fanInvestmentTitle: 'ਇਨਕਲਾਬੀ ਪੱਖਾ ਨਿਵੇਸ਼ ਮਾਡਲ',
    bettingTitle: 'ਭਵਿੱਖ ਦੇ ਸਿਤਾਰਿਆਂ \'ਤੇ ਸੱਟੇਬਾਜ਼ੀ',
    bettingDesc: 'ਡੀਹਬ ਪਹਿਲਾ ਪਲੇਟਫਾਰਮ ਬਣਾਉਂਦਾ ਹੈ ਜਿੱਥੇ ਪ੍ਰਸ਼ੰਸਕ ਵਿੱਤੀ ਤੌਰ \'ਤੇ ਨਿਵੇਸ਼ ਕਰ ਸਕਦੇ ਹਨ ਸਿਰਜਣਹਾਰ ਉਹ ਵਿਸ਼ਵਾਸ ਕਰਦੇ ਹਨ ਕਿ ਸਫਲ ਹੋ ਜਾਣਗੇ. ਸਮੱਗਰੀ ਦੇ ਅੰਸ਼ਾਂ ਨੂੰ ਖਰੀਦ ਕੇ ਐਨਐਫਟੀ, ਸਮਰਥਕ ਇੱਕ ਸਿਰਜਣਹਾਰ ਦੀ ਯਾਤਰਾ ਵਿੱਚ ਹਿੱਸੇਦਾਰ ਬਣ ਜਾਂਦੇ ਹਨ, ਰਿਟਰਨ ਕਮਾਉਂਦੇ ਹਨ ਜਦੋਂ ਉਨ੍ਹਾਂ ਦੇ ਚੁਣੇ ਹੋਏ ਸਿਰਜਣਹਾਰ ਵਿਗਿਆਪਨ ਮਾਲੀਆ, ਸੁਝਾਵਾਂ ਅਤੇ ਹੋਰ ਮੁਦਰੀਕਰਨ ਧਾਰਾਵਾਂ ਦੁਆਰਾ ਸਫਲਤਾ ਪ੍ਰਾਪਤ ਕਰਦੇ ਹਨ.',
    howFracWorks: 'ਅੰਸ਼ਕਾਰੀਕਰਨ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ',
    fracStep1Title: '1. ਮਿੰਟ ਦ ਪੋਸਟ',
    fracStep1Desc: 'ਅੱਪਰ ਚੁਣ ਕੇ ਮਿੰਟ ਕਰੋ, ਤਾਂ ਪੋਸਟ ਇੱਕ ਐਰਸੀ-1155 ਐਨਐਫਟੀ ਬਣ ਜਾਂਦੀ ਜੋ ਸਹੀ 1,000 ਵੰਡਯੋਗ ਹਿੱਸਿਆਂ ਵਿੱਚ ਵੰਡੀ ਹੋਈ ਹੁੰਦੀ ਹੈ। ਇਸਨੂੰ ਛੱਡ ਦਿਓ ਤਾਂ ਪੋਸਟ ਵੀ ਪ੍ਰਕਾਸ਼ਤ ਹੋ ਜਾਂਦੀ ਹੈ — ਤੁਸੀਂ ਬਾਅਦ ਵਿੱਚ ਇਸਨੂੰ ਮਿੰਟ ਕਰ ਸਕਦੇ ਹੋ।',
    fracStep2Title: '2. ਸਿਰਜਣਹਾਰ ਦਾ ਫੈਸਲਾ',
    fracStep2Desc: 'ਸਿਰਜਣਹਾਰ ਚੁਣਦੇ ਹਨ ਕਿ ਉਨ੍ਹਾਂ ਦੇ 1,000 ਭੰਡਾਰਾਂ ਵਿੱਚੋਂ ਕਿੰਨੇ ਆਪਣੀ ਕਮਿ communityਨਿਟੀ ਨੂੰ ਵੇਚਣ, ਰੱਖਣ ਜਾਂ ਵੰਡਣ ਲਈ ਹਨ.',
    fracStep3Title: '3. ਫੈਨ ਇਨਵੈਸਟਮੈਂਟ',
    fracStep3Desc: 'ਸਮਰਥਕ ਅੰਸ਼ ਖਰੀਦਦੇ ਹਨ, ਹਿੱਸੇਦਾਰ ਬਣ ਜਾਂਦੇ ਹਨ ਜੋ ਸਾਰੇ ਮਾਲੀਆ ਧਾਰਾਵਾਂ ਤੋਂ ਅਨੁਪਾਤਕ ਰਿਟਰਨ ਕਮਾਉਂਦੇ ਹਨ.',
    benefitsTitle: 'ਸਾਰੀਆਂ ਪਾਰਟੀਆਂ ਲਈ ਲਾਭ',
    forCreators: 'ਸਿਰਜਣਹਾਰਾਂ ਲਈ',
    forCreatorsDesc: 'ਤਤਕਾਲ ਮੁਦਰੀਕਰਨ, ਕਮਿ communityਨਿਟੀ ਫੰਡਿੰਗ, ਇਕਸਾਰ ਪ੍ਰੋਤਸਾਹਨ, ਅਤੇ ਸਫਲ ਸਮਗਰੀ ਤੋਂ ਲਾਈਫਟਾਈਮ ਪੈਸਿਵ ਆਮਦਨੀ.',
    forFans: 'ਪ੍ਰਸ਼ੰਸਕਾਂ ਲਈ',
    forFansDesc: 'ਵਧ ਰਹੇ ਸਿਤਾਰਿਆਂ, ਵਪਾਰ ਯੋਗ ਸੰਪਤੀਆਂ, ਅਤੇ ਸਿਰਜਣਹਾਰ ਦੀ ਸਫਲਤਾ ਵਿੱਚ ਸਿੱਧੀ ਭਾਗੀਦਾਰੀ ਦਾ ਸਮਰਥਨ ਕਰਨ ਤੋਂ ਵਿੱਤੀ ਉਲਟਾ.',
    forEveryone: 'ਹਰ ਕਿਸੇ ਲਈ',
    forEveryoneDesc: 'ਸੈਂਸਰਸ਼ਿਪ-ਰੋਧਕ, ਆਗਿਆ ਰਹਿਤ ਪ੍ਰਣਾਲੀ ਜੋ ਪਲੇਟਫਾਰਮ ਨਿਰਭਰਤਾ ਤੋਂ ਬਿਨਾਂ ਸਾਰੇ ਭਾਗੀਦਾਰਾਂ ਲਈ ਮੁੱਲ ਬਣਾਉਂਦੀ ਹੈ.',
