    commUser5: 'Web3 ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਨਾਲ ਸਹਿਜ ਏਕੀਕਰਣ',
    superPowersTitle: 'ਸੁਪਰਪਾਵਰ',
    superPowersDesc: 'ਸੁਪਰਪਾਵਰਜ਼ ਇੱਕ ਸਟੈਕਿੰਗ ਬੈਜ ਨੂੰ ਪਹੁੰਚ ਵਿੱਚ ਬਦਲ ਦਿੰਦੇ ਹਨ ਜੋ ਤੁਸੀਂ ਖਰਚ ਕਰ ਸਕਦੇ ਹੋ. ਹਰ ਪੰਦਰਵਾੜੇ ਤੁਹਾਡਾ ਬੈਜ ਗ੍ਰਾਂਟਾਂ ਨੂੰ ਹੁਲਾਰਾ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਇੱਕ ਖਰਚ ਕਰਨਾ ਹੋਮ ਫੀਡ ਦੇ ਸਿਖਰ ਤੇ ਸਲਾਟ ਵਿੱਚ ਇੱਕ ਪੋਸਟ ਪਾਉਂਦਾ ਹੈ. ਟੀਮ ਅਪ ਹਰੇਕ ਲਈ ਖੁੱਲਾ ਹੈ ਅਤੇ ਅੱਠ ਖਾਤਿਆਂ ਤੱਕ ਦੀ ਵਾਲਿਟ ਪਾਵਰ ਨੂੰ ਜੋੜਦਾ ਹੈ, ਜਿਸ ਨਾਲ ਹਰੇਕ ਮੈਂਬਰ ਨੂੰ ਉਨ੍ਹਾਂ ਦੇ ਕੁੱਲ ਅਨਲੌਕ ਮਿਲਦੇ ਹਨ । ਸਲਾਟ ਘੁੰਮਦਾ ਹੈਃ ਜਦੋਂ ਕਈ ਬੂਸਟ ਚੱਲ ਰਹੇ ਹੁੰਦੇ ਹਨ, ਦਰਸ਼ਕਾਂ ਨੂੰ ਬੈਜ ਟੀਅਰ ਦੁਆਰਾ ਇੱਕ ਵਜ਼ਨ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ, ਇਸ ਲਈ ਇੱਕ ਉੱਚ ਪੱਧਰੀ ਵਧੇਰੇ ਅਕਸਰ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਹਰ ਕੋਈ ਅਜੇ ਵੀ ਉਹ ਖਿੜਕੀ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ ਜੋ ਉਨ੍ਹਾਂ ਨੂੰ ਦਿੱਤੀ ਗਈ ਸੀ.',
