    trendJackerDesc2: 'ਆਪਣੀ ਇਕ ਸ਼੍ਰੇਣੀ ਨੂੰ ਟ੍ਰੈਂਡਿੰਗ ਸੂਚੀ ਦੇ ਸਿਖਰ \'ਤੇ ਪਾਓ. ਦੈਂਤ ਟਾਰਟੋਇਸ ਤੇ ਅਨਲੌਕ ਕਰਦਾ ਹੈ । ਹੁਣ ਲਾਈਵ ਕਰੋ ।',
    timelineBomber: '5) ਟਾਈਮਲਾਈਨ ਬੰਬਰ',
    timelineBomberDesc2: 'ਤੁਹਾਡੇ ਪੈਰੋਕਾਰ ਤੁਹਾਡੀ ਪੋਸਟ ਨੂੰ ਕਿਸੇ ਹੋਰ ਦੇ ਉਤਸ਼ਾਹ ਤੋਂ ਪਹਿਲਾਂ ਵੇਖਦੇ ਹਨ — ਇੱਕ ਕਿੰਗ ਕੋਬਰਾ ਉਨ੍ਹਾਂ ਲੋਕਾਂ ਲਈ ਇੱਕ ਮੈਗਲੋਡਨ ਨੂੰ ਕੁੱਟਦਾ ਹੈ ਜਿਨ੍ਹਾਂ ਨੇ ਤੁਹਾਡੇ ਤੋਂ ਸੁਣਨਾ ਚੁਣਿਆ. ਕਿੰਗ ਕੋਬਰਾ ਵਿਖੇ ਅਨਲੌਕ ਕਰਦਾ ਹੈ । ਹੁਣ ਜੀਓ ।',
    precisionStrike: '8) ਸ਼ੁੱਧਤਾ ਹੜਤਾਲ',
    precisionStrikeDesc: 'ਉਨ੍ਹਾਂ ਲੋਕਾਂ ਤੱਕ ਪਹੁੰਚੋ ਜੋ ਤੁਹਾਡੇ ਨਾਮ ਦੇ ਖਾਤੇ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹਨ. ਡਾਲਫਿਨ ਤੇ ਅਨਲੌਕ ਕਰਦਾ ਹੈ । ਹੁਣ ਲਾਈਵ ਕਰੋ ।',
    harpoon: '9) ਹਾਰਪੂਨ',
    harpoonDesc: 'ਬੈਜ ਪੱਧਰਾਂ ਵਿੱਚ ਹਰੇਕ ਧਾਰਕ ਨੂੰ ਸੂਚਿਤ ਕਰੋ ਜੋ ਤੁਸੀਂ ਇੱਕ ਪੋਸਟ ਬਾਰੇ ਚੁਣਦੇ ਹੋ । ਟਾਈਗਰ ਸ਼ਾਰਕ ਵਿਖੇ ਅਨਲੌਕ ਕਰਦਾ ਹੈ । ਹੁਣ ਲਾਈਵ ।',
    superPowersMore2: 'ਸਾਰੀਆਂ ਬਾਰਾਂ ਸ਼ਕਤੀਆਂ ਲਾਈਵ ਹਨ ਅਤੇ ਐਪ ਵਿੱਚ ਸੂਚੀਬੱਧ ਹਨ. Comment ਐਂਕਰ ਤੁਹਾਡੀ ਟਿੱਪਣੀ ਨੂੰ ਕਿਸੇ ਹੋਰ ਦੇ ਧਾਗੇ ਦੇ ਸਿਖਰ \'ਤੇ ਰੱਖਦਾ ਹੈ. ਸਿਗਨਲ ਫਲੇਅਰ ਤੁਹਾਡੇ ਮਗਰ ਆਉਣ ਵਾਲੇ ਹਰ ਖਾਤੇ ਨੂੰ ਇੱਕ ਨੋਟੀਫਿਕੇਸ਼ਨ ਭੇਜਦਾ ਹੈ । ਫਲੈਕ ਜੈਕਟ ਡਾ downਨਵੋਟ ਦਫਨਾਉਣ ਲਈ ਇੱਕ ਪੋਸਟ ਪ੍ਰਤੀਰੋਧਕ ਬਣਾਉਂਦਾ ਹੈ ਜਦੋਂ ਇਹ ਚਲਦਾ ਹੈ. ਟੀਮ ਅੱਪ ਦੇ ਤੌਰ ਤੇ ਬਹੁਤ ਸਾਰੇ ਅੱਠ ਖਾਤੇ ਆਪਣੇ ਬਟੂਏ ਦੀ ਸ਼ਕਤੀ ਨੂੰ ਜੋੜ ਦਿੰਦਾ ਹੈ, ਇਸ ਲਈ ਹਰ ਸਦੱਸ ਆਪਣੇ ਪੂਲ ਬੈਲੰਸ ਅਨਲੌਕ ਬੈਜ ਪਹਿਨਦਾ ਹੈ. ਫਰੰਟ ਕਤਾਰ ਉਸ ਪੜਾਅ ਨੂੰ ਪਾਉਂਦੀ ਹੈ ਜਿਸਦੀ ਤੁਸੀਂ ਮੇਜ਼ਬਾਨੀ ਕਰ ਰਹੇ ਹੋ ਪੜਾਅ ਰੇਲ ਦੇ ਸਿਖਰ\' ਤੇ. ਡੀਪ ਕਰੰਟ ਕਿਸੇ ਹੋਰ ਦੀ ਪੋਸਟ ਨੂੰ ਤੁਹਾਡੇ ਇੱਕ ਬੂਸਟ ਦਿੰਦਾ ਹੈ.',
    superPowersMoreV2: 'ਸਾਰੀਆਂ ਬਾਰਾਂ ਸ਼ਕਤੀਆਂ ਲਾਈਵ ਹਨ ਅਤੇ ਐਪ ਵਿੱਚ ਸੂਚੀਬੱਧ ਹਨ. Comment ਐਂਕਰ ਤੁਹਾਡੀ ਟਿੱਪਣੀ ਨੂੰ ਕਿਸੇ ਹੋਰ ਦੇ ਧਾਗੇ ਦੇ ਸਿਖਰ \'ਤੇ ਰੱਖਦਾ ਹੈ. ਸਿਗਨਲ ਫਲੇਅਰ ਤੁਹਾਡੇ ਮਗਰ ਆਉਣ ਵਾਲੇ ਹਰ ਖਾਤੇ ਨੂੰ ਇੱਕ ਨੋਟੀਫਿਕੇਸ਼ਨ ਭੇਜਦਾ ਹੈ । ਫਲੈਕ ਜੈਕਟ ਡਾ downਨਵੋਟ ਦਫਨਾਉਣ ਲਈ ਇੱਕ ਪੋਸਟ ਪ੍ਰਤੀਰੋਧਕ ਬਣਾਉਂਦਾ ਹੈ ਜਦੋਂ ਇਹ ਚਲਦਾ ਹੈ. ਟੀਮ ਅੱਪ ਦੇ ਤੌਰ ਤੇ ਬਹੁਤ ਸਾਰੇ ਅੱਠ ਖਾਤੇ ਆਪਣੇ ਬਟੂਏ ਦੀ ਸ਼ਕਤੀ ਨੂੰ ਜੋੜ ਦਿੰਦਾ ਹੈ, ਇਸ ਲਈ ਹਰ ਸਦੱਸ ਆਪਣੇ ਪੂਲ ਬੈਲੰਸ ਅਨਲੌਕ ਬੈਜ ਪਹਿਨਦਾ ਹੈ. ਫਰੰਟ ਕਤਾਰ ਉਸ ਪੜਾਅ ਨੂੰ ਪਾਉਂਦੀ ਹੈ ਜਿਸਦੀ ਤੁਸੀਂ ਮੇਜ਼ਬਾਨੀ ਕਰ ਰਹੇ ਹੋ ਪੜਾਅ ਰੇਲ ਦੇ ਸਿਖਰ\' ਤੇ. ਡੀਪ ਕਰੰਟ ਕਿਸੇ ਹੋਰ ਦੀ ਪੋਸਟ ਨੂੰ ਤੁਹਾਡੇ ਇੱਕ ਬੂਸਟ ਦਿੰਦਾ ਹੈ.',
    superPowersLink: 'ਆਪਣਾ ਭੱਤਾ ਅਤੇ ਪੂਰੀ ਪੌੜੀ ਵੇਖੋ',
    spPowersTitle: 'ਬਾਰਾਂ ਸ਼ਕਤੀਆਂ',
    spPowersLead: 'ਬੈਜ ਪੌੜੀ ਦੀ ਹਰ ਰਿੰਗ ਬਿਲਕੁਲ ਇਕ ਸ਼ਕਤੀ ਨੂੰ ਅਨਲੌਕ ਕਰਦੀ ਹੈ, ਅਤੇ ਹਰ ਸ਼ਕਤੀ ਜੋ ਤੁਸੀਂ ਅਨਲੌਕ ਕੀਤੀ ਹੈ ਉਹ ਅਨਲੌਕ ਰਹਿੰਦੀ ਹੈ. ਉਹ ਸਾਰੇ ਇਕੋ ਪੰਦਰਵਾੜੇ ਦੇ ਭੱਤੇ \'ਤੇ ਖਿੱਚਦੇ ਹਨ, ਇਸ ਲਈ ਚੋਣ ਇਹ ਹੈ ਕਿ ਇਸ\' ਤੇ ਕੀ ਖਰਚ ਕਰਨਾ ਹੈ.',
