    spRotationDesc: 'ਸਲਾਟ ਪਿੰਨ ਦੀ ਬਜਾਏ ਘੁੰਮਦਾ ਹੈ. ਜਦੋਂ ਕਈ ਬੂਸਟ ਇਕੋ ਸਮੇਂ ਚੱਲ ਰਹੇ ਹੁੰਦੇ ਹਨ, ਤਾਂ ਹਰੇਕ ਦਰਸ਼ਕ ਨਾਲ ਨਜਿੱਠਿਆ ਜਾਂਦਾ ਹੈ, ਬੂਸਟਰ ਦੇ ਬੈਜ ਟੀਅਰ ਦੁਆਰਾ ਤੋਲਿਆ ਜਾਂਦਾ ਹੈ — ਇੱਕ ਉੱਚ ਪੱਧਰੀ ਵਧੇਰੇ ਅਕਸਰ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਹਰ ਕੋਈ ਅਜੇ ਵੀ ਉਹ ਵਿੰਡੋ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ ਜਿਸਦਾ ਉਹ ਭੁਗਤਾਨ ਕਰਦਾ ਹੈ. ਕੀ ਇੱਕ ਹੁਲਾਰਾ ਖਰੀਦਦਾ ਹੈ ਕੁਝ ਮਿੰਟਾਂ ਲਈ ਆਵਾਜ਼ ਦਾ ਇੱਕ ਹਿੱਸਾ ਹੈ, ਨਾ ਕਿ ਫੀਡ ਦੇ ਸਿਖਰ ਦਾ ਇਕਲੌਤਾ ਕਬਜ਼ਾ.',
    spCycleTitle: 'ਹਰ ਕਿਸੇ ਲਈ ਇੱਕ ਘੜੀ',
    spCycleDesc: 'ਚੱਕਰ ਇੱਕ ਪਲੇਟਫਾਰਮ-ਵਿਆਪਕ ਚੌਦਾਂ ਦਿਨ ਹੈ, ਇਸ ਲਈ ਹਰ ਕਿਸੇ ਦਾ ਭੱਤਾ ਉਸੇ ਸਮੇਂ ਦੁਬਾਰਾ ਭਰਦਾ ਹੈ. ਕੁਝ ਵੀ ਖਤਮ ਨਹੀਂ ਹੁੰਦਾ । ਬੁਕਿੰਗ ਸ਼ੁਰੂ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਰੱਦ ਕਰੋ ਅਤੇ ਮਿੰਟ ਉਸ ਚੱਕਰ ਵਿੱਚ ਵਾਪਸ ਚਲੇ ਜਾਂਦੇ ਹਨ ਜਿਸਦਾ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਨੂੰ ਭੁਗਤਾਨ ਕੀਤਾ ਸੀ ।',
    spSafetyTitle: 'ਇੱਕ ਹੁਲਾਰਾ ਕੀ ਨਹੀਂ ਕਰ ਸਕਦਾ',
    spSafetyDesc: 'ਹਰ ਡਰਾਅ ਪੋਸਟ ਦੇ ਵਿਰੁੱਧ ਦੁਬਾਰਾ ਜਾਂਚਿਆ ਜਾਂਦਾ ਹੈ ਕਿਉਂਕਿ ਇਹ ਉਸ ਪਲ ਤੇ ਖੜ੍ਹਾ ਹੁੰਦਾ ਹੈ, ਇਸ ਲਈ ਇੱਕ ਪੋਸਟ ਜੋ ਉਦੋਂ ਤੋਂ ਹਟਾ ਦਿੱਤੀ ਗਈ ਹੈ, ਬਲੌਕ ਕੀਤੀ ਗਈ ਹੈ ਜਾਂ ਨਿਸ਼ਾਨਬੱਧ ਕੀਤੀ ਗਈ ਹੈ ਪਰਿਪੱਕ ਕਦੇ ਵੀ ਕਿਸੇ ਅਜਨਬੀ ਦੀ ਫੀਡ ਤੱਕ ਨਹੀਂ ਪਹੁੰਚਦੀ. ਪਰਿਪੱਕ ਪੋਸਟਾਂ ਨੂੰ ਬੁਕਿੰਗ ਕਰਨ ਤੋਂ ਵੀ ਇਨਕਾਰ ਕਰ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਕਿਸੇ ਅਜਿਹੇ ਵਿਅਕਤੀ ਨਾਲ ਕਦੇ ਵੀ ਹੁਲਾਰਾ ਨਹੀਂ ਦਿੱਤਾ ਜਾਂਦਾ ਜਿਸਨੇ ਤੁਹਾਨੂੰ ਰੋਕਿਆ ਹੋਵੇ ਜਾਂ ਜਿਸ ਵਿਅਕਤੀ ਨੂੰ ਤੁਸੀਂ ਹੁਲਾਰਾ ਦਿੱਤਾ ਹੋਵੇ ।',
