    feedsTitle: 'ਫੀਡ ਅਤੇ ਸਮੱਗਰੀ ਫਾਰਮੈਟ',
    feedsDesc: 'ਡੀਹਬ ਹੋਮ ਸਤਹ ਇੱਕ ਸਿੰਗਲ ਟੈਬਡ ਫੀਡ ਹੈ ਜੋ ਹਰ ਸਮਗਰੀ ਫਾਰਮੈਟ ਨੂੰ ਇਕੋ ਸਮੇਂ ਲੈ ਜਾਂਦੀ ਹੈ. ਸਿਰਜਣਹਾਰਾਂ ਨੂੰ ਇੱਕ ਮਾਧਿਅਮ ਵਿੱਚ ਮਜਬੂਰ ਕਰਨ ਦੀ ਬਜਾਏ, ਫੀਡ ਟੈਕਸਟ, ਚਿੱਤਰ, ਲੰਬੇ ਰੂਪ ਵਾਲੇ ਵੀਡੀਓ, ਸ਼ਾਰਟ-ਫਾਰਮ ਰੀਲ, ਸੰਗੀਤ ਅਤੇ ਲਾਈਵ ਸਟ੍ਰੀਮ ਨੂੰ ਇੱਕ ਸਕ੍ਰੌਲ ਵਿੱਚ ਮਿਲਾਉਂਦੀ ਹੈ, ਅਤੇ ਦਰਸ਼ਕਾਂ ਨੂੰ ਇੱਕ ਸਿੰਗਲ ਫਾਰਮੈਟ ਵਿੱਚ ਤੰਗ ਕਰਨ ਦਿੰਦੀ ਹੈ ਜਦੋਂ ਵੀ ਉਹ ਚਾਹੁੰਦੇ ਹਨ. ਹਰ ਕਾਰਡ, ਫਾਰਮੈਟ ਦੀ ਪਰਵਾਹ ਕੀਤੇ ਬਿਨਾਂ, ਉਹੀ ਸਮਾਜਿਕ ਅਤੇ ਮੁਦਰੀਕਰਨ ਨਿਯੰਤਰਣ ਰੱਖਦਾ ਹੈਃ ਜਿਵੇਂ ਕਿ, ਟਿੱਪਣੀ, ਰੀਪੋਸਟ, ਹਵਾਲਾ, ਬੁੱਕਮਾਰਕ ਅਤੇ ਡੀਹਬ ਟੋਕਨ ਵਿਚ ਟਿਪ.',
    feedsDesc2: 'ਫਾਰਮੈਟ ਫੀਡ ਦੇ ਸਿਖਰ \'ਤੇ ਟੈਬਾਂ ਵਜੋਂ ਸਾਹਮਣੇ ਆਉਂਦੇ ਹਨ. ਡਿਫੌਲਟ ਹੋਮ ਟੈਬ ਉਨ੍ਹਾਂ ਲੋਕਾਂ ਅਤੇ ਕਮਿ communitiesਨਿਟੀਆਂ ਤੋਂ ਹਰ ਚੀਜ ਨੂੰ ਆਪਸ ਵਿੱਚ ਜੋੜਦੀ ਹੈ ਜਿਨ੍ਹਾਂ ਦੀ ਤੁਸੀਂ ਪਾਲਣਾ ਕਰਦੇ ਹੋ; ਸਮਰਪਿਤ ਟੈਬਾਂ ਇੱਕ ਮਾਧਿਅਮ ਨੂੰ ਅਲੱਗ ਕਰਦੀਆਂ ਹਨ ਤਾਂ ਜੋ ਤੁਸੀਂ, ਉਦਾਹਰਣ ਵਜੋਂ, ਸਿਰਫ ਲੰਬੇ ਰੂਪ ਵਾਲੇ ਵੀਡੀਓ ਜਾਂ ਸਿਰਫ ਸੰਗੀਤ ਨੂੰ ਬ੍ਰਾਉਜ਼ ਕਰ ਸਕੋ. ਰੈਂਕਿੰਗ ਨੂੰ ਪਲੇਟਫਾਰਮ ਲੀਡਰਬੋਰਡ ਐਲਗੋਰਿਦਮ ਦੁਆਰਾ ਚਲਾਇਆ ਜਾਂਦਾ ਹੈ ਜੋ ਇਸ ਪੰਨੇ ਨੂੰ ਹੋਰ ਹੇਠਾਂ ਦਸਤਾਵੇਜ਼ਿਤ ਕਰਦਾ ਹੈ, ਇਸ ਲਈ ਗੁਣਵੱਤਾ ਅਤੇ ਸ਼ਮੂਲੀਅਤ, ਵਿਗਿਆਪਨ ਖਰਚ ਨਹੀਂ, ਪਹੁੰਚ ਦਾ ਫੈਸਲਾ ਕਰੋ.',
    feedsHome: 'ਹੋਮ ਫੀਡ:',
    feedsShorts: 'ਸ਼ਾਰਟਸ:',
    feedsShortsDesc: 'ਟਿਕਟੋਕ-ਸ਼ੈਲੀ ਦੇਖਣ ਲਈ ਇੱਕ ਲੰਬਕਾਰੀ, ਸਵਾਈਪ ਕਰਨ ਯੋਗ ਸ਼ਾਰਟ-ਵੀਡੀਓ ਰੀਲ. ਦਿਸ਼ਾ-ਲਾਕ ਕੀਤੇ ਸਵਾਈਪ ਇਸ਼ਾਰੇ ਕਲਿੱਪਾਂ ਦੇ ਵਿਚਕਾਰ ਚਲਦੇ ਹਨ, ਮੋਮੈਂਟਮ ਨੂੰ ਸੀਮਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਤਾਂ ਜੋ ਤੁਸੀਂ ਕਦੇ ਵੀ ਇਕੋ ਸਮੇਂ ਦੋ ਨੂੰ ਨਾ ਛੱਡੋ, ਅਤੇ ਮੁਦਰੀਕਰਨ ਹਰ ਕਲਿੱਪ ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ.',
    feedsStories: 'ਕਹਾਣੀਆਂ:',
    feedsStoriesDesc: 'ਐਪ ਵਿੱਚ ਸਿੱਧੇ ਤੌਰ \'ਤੇ ephemeral ਕਹਾਣੀਆ ਨੂੰ ਰਿਕਾਰਡ ਕਰੋ. ਓਵਰਲੇ ਸੰਪਾਦਕ ਫੀਡ ਦੇ ਸਿਖਰ\' ਤੇ ਸਟੋਰੀਜ਼ ਬਾਰ \'ਤੇ ਪ੍ਰਕਾਸ਼ਤ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਟੈਕਸਟ, ਇਮੋਜੀ ਅਤੇ ਸਟਿੱਕਰ ਸ਼ਾਮਲ ਕਰਦਾ ਹੈ, ਜਿੱਥੇ ਉਹ 24 ਘੰਟਿਆਂ ਬਾਅਦ ਖਤਮ ਹੋ ਜਾਂਦੇ ਹਨ.',
    feedsPolls: 'ਪੋਲ:',
    feedsPollsDesc: 'ਪੋਲ ਪੋਸਟਾਂ ਬਣਾਓ ਅਤੇ ਫੀਡ ਵਿੱਚ ਵੋਟਾਂ ਇਨਲਾਈਨ ਇਕੱਤਰ ਕਰੋ. ਨਤੀਜੇ ਲਾਈਵ ਅਪਡੇਟ ਕਰਦੇ ਹਨ ਅਤੇ ਕਮਿ communityਨਿਟੀ ਫੈਸਲਿਆਂ ਜਾਂ ਸ਼ਾਸਨ ਦੀ ਭਾਵਨਾ ਨੂੰ ਚਲਾਉਣ ਲਈ ਵਰਤੇ ਜਾ ਸਕਦੇ ਹਨ.',
    feedsTabs: 'ਸਮਰਪਿਤ ਟੈਬ:',
    feedsTabsDesc: 'ਇੱਕ ਵਾਰ ਵਿੱਚ ਇੱਕ ਸਿੰਗਲ ਫਾਰਮੈਟ ਨੂੰ ਬ੍ਰਾਉਜ਼ ਕਰਨ ਲਈ ਵੀਡੀਓ, ਚਿੱਤਰ, ਸੰਗੀਤ ਅਤੇ ਲਾਈਵ ਟੈਬਾਂ ਵਿਚਕਾਰ ਸਵਿਚ ਕਰੋ, ਹਰ ਇੱਕ ਇਸਦੇ ਆਪਣੇ ਲੇਆਉਟ ਨਾਲ ਉਸ ਮਾਧਿਅਮ ਨੂੰ ਟਿਊਨ ਕੀਤਾ ਜਾਂਦਾ ਹੈ.',
