    settingsB5Desc: 'ਪ੍ਰਤੀ-ਸ਼੍ਰੇਣੀ ਤੁਹਾਨੂੰ ਦੱਸਣ ਦੇ ਯੋਗ ਕੀ ਹੈ, ਬ੍ਰਾ browserਜ਼ਰ ਨੋਟੀਫਿਕੇਸ਼ਨ, ਅਤੇ ਈਮੇਲ ਨੋਟੀਫਿਕੇਸ਼ਨਾਂ ਲਈ ਵੱਖਰੇ ਤੌਰ ਤੇ ਸਵਿੱਚ ਕਰਦਾ ਹੈ.',
