    streamingLabel: 'ਗੱਲਬਾਤ ਤੋਹਫ਼ੇ (g)',
    streamingLabelDesc: 'ਹਰੇਕ ਸਟ੍ਰੀਮ ਦਾ ਆਪਣਾ ਚੈਟ ਰੂਮ ਹੁੰਦਾ ਹੈ ਜਿਸ ਵਿੱਚ ਇਸ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਣ ਅਤੇ ਤੋਹਫ਼ੇ ਦਿਖਾਏ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਮੇਜ਼ਬਾਨ ਇੱਕ ਕੰਸੋਲ ਤੋਂ ਪ੍ਰਸਾਰਣ ਚਲਾਉਂਦਾ ਹੈ ਜੋ ਦਰਸ਼ਕਾਂ, ਪਸੰਦਾਂ ਅਤੇ ਸੁਝਾਆਂ ਨੂੰ ਦਰਸਾਉਂਦਾ ਹੈ',
    subsDesc: 'ਸਿਰਜਣਹਾਰ ਆਪਣੀ ਪ੍ਰੋਫਾਈਲ ਤੋਂ ਸਿੱਧੇ ਗਾਹਕੀ ਵੇਚਦੇ ਹਨ. ਯੋਜਨਾਵਾਂ ਦੀ ਕੀਮਤ ਯੂਐਸ ਡਾਲਰ ਵਿੱਚ ਹੁੰਦੀ ਹੈ ਅਤੇ ਲਾਈਵ ਕੀਮਤ ਤੇ ਡੀਹਬ ਟੋਕਨ ਵਿੱਚ ਅਦਾ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਸਿਰਜਣਹਾਰ ਦਾ ਹਿੱਸਾ ਸਿੱਧਾ ਉਨ੍ਹਾਂ ਦੇ ਬਟੂਏ ਵਿੱਚ, ਘੱਟ ਡੀਹਬ ਦੀ ਬੈਜ-ਪੱਧਰ ਦੀ ਫੀਸ. ਸਿਰਫ ਗਾਹਕਾਂ ਦੀਆਂ ਪੋਸਟਾਂ ਇੱਕ ਅਸਲ ਗੇਟ ਹਨਃ ਜਿਨ੍ਹਾਂ ਲੋਕਾਂ ਨੇ ਗਾਹਕੀ ਨਹੀਂ ਲਈ ਹੈ ਉਹ ਇੱਕ-ਲਾਈਨ ਟੀਜ਼ਰ ਵੇਖਦੇ ਹਨ, ਨਾ ਕਿ ਪੋਸਟ.',
