    forCreatorsSubs5: 'ਪੈਸੇ ਤੁਰੰਤ ਵਸੂਲ ਕੀਤੇ ਜਾਂਦੇ ਹਨ, ਪਰ ਤੁਹਾਡੇ ਬੈਡਜ \'ਤੇ ਲੱਗਣ ਵਾਲੀ ਫੀਸ ਘੱਟ ਜਾਂਦੀ ਹੈ।',
    forSubs2: 'ਸਿਰਫ ਗਾਹਕਾਂ ਦੀਆਂ ਪੋਸਟਾਂ, ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਗਾਹਕੀ ਲੈਂਦੇ ਹੋ ਉਦੋਂ ਤੱਕ ਅਨਲੌਕ ਕੀਤਾ ਜਾਂਦਾ ਹੈ',
