    messagesDesc: 'ਡੀਹਬ \'ਤੇ ਸਿੱਧੇ ਸੰਦੇਸ਼ ਡਿਫੌਲਟ ਤੌਰ\' ਤੇ ਐਂਡ-ਟੂ-ਐਂਡ ਇਨਕ੍ਰਿਪਟਡ ਹੁੰਦੇ ਹਨ, ਮੁਦਰੀਕ੍ਰਿਤ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ, ਅਤੇ ਉਨ੍ਹਾਂ ਨਿਯੰਤਰਣਾਂ ਦੇ ਨਾਲ ਆਉਂਦੇ ਹਨ ਜਿਨ੍ਹਾਂ ਦੀ ਤੁਸੀਂ ਇੱਕ ਆਧੁਨਿਕ ਮੈਸੇਂਜਰ ਤੋਂ ਉਮੀਦ ਕਰੋਗੇ. ਟੈਕਸਟ ਭੇਜਣ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਡੀ ਡਿਵਾਈਸ \'ਤੇ ਸੀਲ ਕੀਤਾ ਜਾਂਦਾ ਹੈ, ਸਿਰਜਣਹਾਰ ਲੋਕਾਂ ਤੋਂ ਉਨ੍ਹਾਂ ਨੂੰ ਸੁਨੇਹਾ ਭੇਜਣ ਲਈ ਚਾਰਜ ਲੈ ਸਕਦੇ ਹਨ, ਅਤੇ ਸਕ੍ਰੀਨ ਦੇ ਕੋਨੇ\' ਤੇ ਗੱਲਬਾਤ ਡੌਕ ਕਰ ਸਕਦੇ ਹਨ ਤਾਂ ਜੋ ਤੁਸੀਂ ਗੱਲਬਾਤ ਕਰਦੇ ਸਮੇਂ ਬ੍ਰਾਊਜ਼ਿੰਗ ਜਾਰੀ ਰੱਖ ਸਕੋ ।',
    msg4: 'ਫੋਟੋਆਂ, ਵੀਡੀਓ, ਜੀਆਈਐਫ ਅਤੇ ਪੇਸਟ ਕੀਤੀਆਂ ਤਸਵੀਰਾਂ',
