    msg9: 'ਅੱਗੇ ਵੱਲ ਸਵਾਈਪ ਕਰਕੇ ਕਿਸੇ ਚੈਟ ਨੂੰ ਬਲਾਕ ਜਾਂ ਡੀਲੀਟ ਕਰੋ; ਡੀਲੀਟ ਕਰਨ \'ਤੇ ਪੰਜ ਸਕਿੰਟਾਂ ਤੱਕ ਪਿਛਲਾ ਕਰਨ ਦੀ ਸੰਭਾਵਨਾ ਰਹਿੰਦੀ ਹੈ।',
