    privateByDesignDesc: 'DeHub ਸਿਰਫ਼ ਐਨਕ੍ਰਿਪਟਡ ਮੈਸੇਜਾਂ ਲਈ ਸਿਫਰਟੈਕਸਟ ਹੀ ਸਟੋਰ ਕਰਦਾ ਹੈ। ਤੁਹਾਡੇ ਕੀਜ਼ ਤੁਹਾਡੇ ਡਿਵਾਈਸ ਉੱਤੇ ਇੱਕ ਵਾਲੈਟ ਸਿਗਨਚਰ ਤੋਂ ਨਿਕਲਦੇ ਹਨ ਅਤੇ ਅਸੀਂ ਕਦੇ ਵੀ ਉਹਨਾਂ ਨੂੰ ਭੇਜਦੇ ਨਹੀਂ।',
    secureMediaSharing: 'ਕੀ ਏਨਕ੍ਰਿਪਟਡ ਨਹੀਂ ਹੈ',
