    moreB3Desc: 'ਲਾਈਵ ਸਾਈਟ ਦੇ ਅੰਕੜੇ — ਸੈਲਾਨੀ, ਪੇਜ ਵਿਯੂਜ਼ ਅਤੇ ਕਮਿ communityਨਿਟੀ ਨੰਬਰ, ਦਿਨ, ਸਾਲ ਜਾਂ ਸਾਰੇ ਸਮੇਂ ਦੁਆਰਾ — ਅੰਦਰੂਨੀ ਰੱਖਣ ਦੀ ਬਜਾਏ ਪ੍ਰਕਾਸ਼ਤ ਕੀਤੇ ਗਏ, ਉਸੇ ਪੰਨੇ \'ਤੇ ਸਥਾਈ ਫੀਡਬੈਕ ਹੱਬ ਦੇ ਨਾਲ.',
