    intro1: 'ਗੇਮਰਾਂ ਅਤੇ ਸਟ੍ਰੀਮਰਾਂ ਨਾਲ ਭਰੀ ਇੱਕ ਟੀਮ ਹੋਣ ਦੇ ਨਾਤੇ, ਅਸੀਂ ਬਹੁਤ ਸਾਰੇ ਮਜ਼ੇਦਾਰ, ਮੁਫਤ ਆਰਕੇਡ ਗੇਮਜ਼ ਬਣਾਏ ਅਤੇ ਜਾਰੀ ਕੀਤੇ ਅਤੇ ਆਪਣੀ ਪਹਿਲੀ ਫਲੈਗਸ਼ਿਪ ਗੇਮ ਵੱਲ ਕੰਮ ਕਰ ਰਹੇ ਹਾਂ, ਲਾਸਟ ਚਾਡ ਸਟੈਂਡਿੰਗ, ਪਹਿਲੀ ਕਦੇ ਐਮਐਮਏ ਬੈਟਲ ਰਾਇਲ, ਯੂਬੀਸੌਫਟ ਦੀ ਪਸੰਦ ਦੇ ਦੇ ਦੇਵਜ਼ ਦੀ ਟੀਮ ਦੇ ਨਾਲ ਨਾਲ ਯੂਐਫਸੀ, ਓਕਟਾਗਨ ਅਤੇ ਪੀਐਫਐਲ ਸਿਤਾਰਿਆਂ ਨਾਲ ਭਾਰੀ ਸ਼ਾਮਲ ਇੱਕ ਸੰਸਥਾਪਕ ਟੀਮ, ਜੋਰਜ ਮਾਸਵੀਡਲ ਵਰਗੇ ਚੈਂਪਾਂ ਨਾਲ ਦਸਤਾਵੇਜ਼ੀ ਫਿਲਮਾਂ ਨੂੰ ਫਿਲਮਾਉਂਦੀ ਹੈ, ਅਤੇ ਕੋਨੋਰ ਮੈਕਗ੍ਰੇਗਰ ਦੇ ਕੋਚ ਕਵਾਨਾ ਦੇ ਅਧੀਨ ਸਿਖਲਾਈ ਦਿੱਤੀ ਗਈ. ਦਸਤਾਵੇਜ਼ੀ ਫਿਲਮਾਂ ਨੂੰ ਐਂਡਰਿ T ਟੇਟ ਦੇ ਵਾਰ ਰੂਮ ਦੇ ਮੁਖੀ ਅਤੇ ਸਾਬਕਾ ਯੂਐਫਸੀ ਸਲਗਰ, ਲੂਕ ਬਾਰਨਟ ਦੁਆਰਾ ਡੀਹਬ ਦੇ ਬੇਹਾਲਫ \'ਤੇ ਵੀ ਫਿਲਮਾਇਆ ਗਿਆ ਸੀ.',
    intro2: 'ਸ਼ਮੂਲੀਅਤ, ਸਕਾਰਾਤਮਕ ਫੀਡਬੈਕ ਲੂਪਾਂ ਅਤੇ ਆਮ ਵਿਕਾਸ ਨੂੰ ਉਤਸ਼ਾਹਤ ਕਰਨ ਲਈ ਇਹ ਸੁਨਿਸ਼ਚਿਤ ਕਰਨ ਲਈ ਕਿ ਕੋਈ ਪਤਲਾਪਣ ਜਾਂ ਮਹਿੰਗਾਈ ਦੀ ਜ਼ਰੂਰਤ ਨਹੀਂ ਹੈ.',
    intro3: 'ਇਸ ਨਾਲ ਟੀਮ ਅਤੇ ਕਮਿ communityਨਿਟੀ ਨੂੰ ਸਾਂਝੇ ਟੀਚੇ ਨੂੰ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਨਿਰੰਤਰ ਮਿਹਨਤ ਕਰਨ ਲਈ ਉਤਸ਼ਾਹਤ ਕਰਨ ਦਾ ਵਾਧੂ ਲਾਭ ਵੀ ਮਿਲਦਾ ਹੈ ਜਿੰਨਾ ਜ਼ਿਆਦਾ ਉਪਭੋਗਤਾ ਸਾਡੇ ਕੋਲ ਹਨ, ਜਿੰਨਾ ਜ਼ਿਆਦਾ ਆਮਦਨੀ ਅਸੀਂ ਕਮਾਉਂਦੇ ਹਾਂ, ਉੱਨਾ ਜ਼ਿਆਦਾ ਇਨਾਮ ਪੈਦਾ ਹੁੰਦੇ ਹਨ ਅਤੇ ਜਿੰਨਾ ਜ਼ਿਆਦਾ ਉਪਭੋਗਤਾ ਅਸੀਂ ਆਕਰਸ਼ਤ ਕਰ ਸਕਦੇ ਹਾਂ.',
    intro4: 'ਇੱਕ ਸੱਚਮੁੱਚ ਸਵੈ-ਨਿਰਭਰ ਅਤੇ ਟਿਕਾable ਵਾਤਾਵਰਣ ਪ੍ਰਣਾਲੀ.',
