    introDesc2: 'ਜਿਵੇਂ ਕਿ ਹੋਰ ਅਲਾਟਮੈਂਟਾਂ ਹੁਣ ਗਤੀਸ਼ੀਲ ਹੋਣਗੀਆਂ, ਪ੍ਰੋਟੋਕੋਲ ਫੀਸਾਂ \'ਤੇ ਨਿਰਭਰ ਹੋਣਗੀਆਂ, ਅਹੁਦੇ ਕਿਸੇ ਵੀ ਸਮੇਂ ਜ਼ਰੂਰਤਾਂ ਦੇ ਅਧੀਨ ਹੋਣਗੇ, ਇਹ ਸੁਨਿਸ਼ਚਿਤ ਕਰਦੇ ਹੋਏ ਕਿ ਪ੍ਰੋਟੋਕੋਲ ਦੀਆਂ ਜ਼ਰੂਰਤਾਂ ਹਰ ਸਮੇਂ ਸਭ ਤੋਂ ਅੱਗੇ ਹਨ. ਸਟੈਕਿੰਗ ਪ੍ਰੋਟੋਕੋਲ ਨੂੰ ਵੀ ਜਲਦੀ ਹੀ ਬੇਸ\' ਤੇ ਰਿਲੀਜ਼ ਹੋਣ ਦੇ ਨਾਲ ਇਸ ਸਮੇਂ ਅਪਗ੍ਰੇਡ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ ।',
    technicals: 'ਤਕਨੀਕੀ',
