    commitmentDesc: 'ਅਸੀਂ DeHub \'ਤੇ ਇਹ ਮੰਨਦੇ ਹਾਂ ਕਿ ਗੋਪਨੀਯਤਾ ਇੱਕ ਅਧਿਕਾਰ ਹੈ। ਐਨਕ੍ਰਿਪਟਡ ਮੈਸੇਜਾਂ ਨੂੰ ਗਣਿਤ ਦੁਆਰਾ ਸੁਰੱਖਿਅਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ, ਨਾ ਕਿ ਸਿਰਫ ਨੀਤੀਆਂ ਦੁਆਰਾ, ਜਿਸ ਲਈ ਔਡਿਟ ਕੀਤੇ ਗਏ ਅਤੇ ਵਿਆਪਕ ਤੌਰ \'ਤੇ ਸਮੀਖਿਆ ਕੀਤੇ ਗਏ ਕ੍ਰਿਪਟੋਗ੍ਰਾਫਿਕ ਲਾਇਬ੍ਰੇਰੀਆਂ ਅਤੇ ਐਲਗੋਰਿਥਮਾਂ ਦੀ ਵਰਤੋਂ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਜੇਕਰ ਕੁਝ ਅਜੇ ਤੱਕ ਐਨਕ੍ਰਿਪਟ ਨਹੀਂ ਹੈ — ਫੋਟੋ, ਵੀਡੀਓ ਅਤੇ ਫਾਈਲਾਂ, ਜਾਂ ਕਿਸੇ ਨਾਲ ਇੱਕ ਚਰਚਾ ਜਿਸਨੇ ਐਨਕ੍ਰਿਪਸ਼ਨ ਅਨਲੌਕ ਨਹੀਂ ਕੀਤਾ ਹੈ — ਤਾਂ ਅਸੀਂ ਇਸ ਨੂੰ ਸਪੱਸ਼ਟ ਤੌਰ \'ਤੇ ਕਹਿ ਦਿੰਦੇ ਹਾਂ।',
