    lostRoi: 'ਗੁੰਮ ROI:',
    lostRoiDesc: 'ਬ੍ਰਾਂਡਾਂ ਨੂੰ ਟੀਚਿਆਂ ਦੀ ਪ੍ਰਾਪਤੀ ਤੋਂ ਰੋਕਦਾ ਹੈ, ਇੱਥੋਂ ਤਕ ਕਿ ਵੱਡੀਆਂ ਮੁਹਿੰਮਾਂ ਦੇ ਨਾਲ ਵੀ.',
    howItWorks: 'ਇਹ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ',
    howItWorksDesc1: 'ਜਿੰਨੀ ਜ਼ਿਆਦਾ ਤੁਹਾਡੀਆਂ ਕੁੱਲ ਹੋਲਡਿੰਗਜ਼, ਜਿੰਨੀ ਉੱਚ ਰੈਂਕਿੰਗ ਦਾ ਬੈਜ ਤੁਸੀਂ ਅਨਲੌਕ ਕਰਦੇ ਹੋ, ਤੁਸੀਂ ਇਸ਼ਤਿਹਾਰਾਂ ਤੋਂ ਜਿੰਨੀ ਜ਼ਿਆਦਾ ਕਮਾਈ ਕਰਦੇ ਹੋ, ਓਨੀ ਹੀ ਜ਼ਿਆਦਾ ਕੰਪਨੀਆਂ ਤੁਹਾਨੂੰ ਇਸ਼ਤਿਹਾਰ ਦੇਣ ਲਈ ਭੁਗਤਾਨ ਕਰਦੀਆਂ ਹਨ.',
    howItWorksDesc2: 'ਇਸ ਤਰ੍ਹਾਂ ਪੂਰੇ ਈਕੋਸਿਸਟਮ ਨੂੰ ਲਾਭ ਹੁੰਦਾ ਹੈ ਨਾ ਕਿ ਸਿਰਫ ਇਕ ਪਾਰਟੀ ਨੂੰ. ਪਲੇਟਫਾਰਮ \'ਤੇ ਵਿਗਿਆਪਨ ਦੇਣ ਵਾਲੇ ਸਮਗਰੀ ਨਿਰਮਾਤਾ, ਖਪਤਕਾਰ, ਧਾਰਕ ਅਤੇ ਕੰਪਨੀਆਂ ਸਾਰੇ ਵਧੇਰੇ ਇਨਾਮ ਪ੍ਰਾਪਤ ਕਰਦੇ ਹਨ.',
    howItWorksDesc3: 'ਵਿੱਤੀ ਡੇਟਾ ਸਭ ਤੋਂ ਵੱਧ ਮੁਨਾਫਾ ਹੁੰਦਾ ਹੈ, ਅਤੇ ਸਾਡਾ ਵਿਲੱਖਣ ਰੂਪ ਵਿੱਚ ਇੱਕ ਸਿਸਟਮ ਵਿੱਚ ਜੋੜਿਆ ਜਾਂਦਾ ਹੈ ਵਿਗਿਆਪਨਕਰਤਾ ਸਰੋਤਿਆਂ ਨੂੰ ਨਿਸ਼ਾਨਾ ਬਣਾਉਣ ਲਈ ਵਰਤ ਸਕਦੇ ਹਨ. ਇਹ ਕੁਝ ਅਜਿਹਾ ਵੀ ਨਹੀਂ ਹੈ ਜੋ ਤੁਸੀਂ ਆਫ-ਚੇਨ ਕਰ ਸਕਦੇ ਹੋ, ਕਿਉਂਕਿ ਬੈਂਕ ਸਟੇਟਮੈਂਟਾਂ ਨਿਜੀ ਹਨ ਜਦੋਂ ਕਿ ਬਲਾਕਚੇਨ ਜਨਤਕ ਹੈ.',
    howItWorksDesc4: 'ਸਮੁੰਦਰ ਵਿਚ ਛੋਟੀਆਂ ਮੱਛੀਆਂ ਲਈ ਵਿਸ਼ੇਸ਼ ਸੌਦਿਆਂ ਜਾਂ ਛੋਟਾਂ ਨੂੰ ਤਿਆਰ ਕਰਦੇ ਹੋਏ ਵ੍ਹੇਲ ਅਤੇ ਵੱਡੇ ਖਰਚਿਆਂ ਨੂੰ ਨਿਸ਼ਾਨਾ ਬਣਾਉਣ ਦੇ ਯੋਗ ਹੋਣ ਨਾਲ ਵਿਸ਼ਵ ਭਰ ਵਿਚ ਇਸ਼ਤਿਹਾਰਬਾਜ਼ੀ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀ ਹੈ ਇਸ ਨੂੰ ਦੁਬਾਰਾ ਰੂਪ ਦਿੱਤਾ ਜਾਵੇਗਾ. ਕੋਈ ਇਹ ਕਿਉਂ ਨਹੀਂ ਚਾਹੇਗਾ?',
    preventFraud: 'ਇਹ ਧੋਖਾਧੜੀ ਨੂੰ ਕਿਵੇਂ ਰੋਕਦਾ ਹੈ?',
    preventFraudDesc1: 'ਬੋਟਿੰਗ ਘੱਟ ਲਾਭਕਾਰੀ ਬਣ ਜਾਂਦੀ ਹੈ ਜਦੋਂ ਕਿ ਗਤੀਵਿਧੀ ਟਰੈਕਯੋਗ ਆਨ-ਚੇਨ ਹੁੰਦੀ ਹੈ, ਆਸਾਨੀ ਨਾਲ ਮਾੜੇ ਅਦਾਕਾਰਾਂ ਨੂੰ ਜੋੜਦੀ ਹੈ ਅਤੇ ਆਖਰਕਾਰ ਪੂਰੇ ਉਪਭੋਗਤਾ ਅਧਾਰ ਨੂੰ ਕਯੂਰੇਟ ਕਰਦੀ ਹੈ. ਇਸ਼ਤਿਹਾਰ ਦੇਣ ਵਾਲੇ ਉੱਚ ਰੈਂਕਾਂ ਨੂੰ ਨਿਸ਼ਾਨਾ ਬਣਾਉਂਦੇ ਹਨ, ਘੱਟ ਤੋਂ ਘੱਟ ਕੱractਣ ਯੋਗ ਮੁੱਲ ਨੂੰ ਹੇਠਲੀ ਪਰਤ \'ਤੇ ਛੱਡ ਦਿੰਦੇ ਹਨ, ਜਿੱਥੇ ਕੋਈ ਬਾਕੀ ਧੋਖਾਧੜੀ ਬਾਕੀ ਰਹਿੰਦੀ ਹੈ. ਇਸਦੇ ਸਿਖਰ ਤੇ, ਸਾਡਾ ਵਿਕੇਂਦਰੀਕਰਣ ਸੰਜਮ ਵਧੇਰੇ ਕੁਸ਼ਲ ਨਾਜਾਇਜ਼ ਗਤੀਵਿਧੀਆਂ ਦੀ ਖੋਜ ਅਤੇ ਰੋਕਥਾਮ ਦੀ ਆਗਿਆ ਦਿੰਦਾ ਹੈ.',
    preventFraudDesc2: 'ਮੇਰੇ ਐਡ ਰਿਵਨਿਊ ਸ਼ੇਅਰਿੰਗ ਬਾਰੇ ਵਧੇਰੇ ਜਾਣਕਾਰੀ ਲਈ ਇਸ ਥਰੈਡ ਅਤੇ ਹੇਠਾਂ ਦਿੱਤੇ ਵਾਈਟਪੇਪਰ ਨੂੰ ਦੇਖੋ। ਤੁਸੀਂ ਅਪਲੀਕੇਸ਼ਨ ਦੇ ਨਵੇਂ ਫੀਚਰਾਂ ਅਤੇ ਅਪਡੇਟਾਂ ਬਾਰੇ ਸਭ ਤੋਂ ਨਵੀਂ ਖ਼ਬਰਾਂ ਲਈ ਅਸੀਂ ਨੂੰ ਫ਼ਾਲੋ ਕਰਨ ਵਿੱਚ ਵੀ ਯਕੀਨੀ ਬਣਾਓ।',
    dashboardPreview: 'ਇਸ਼ਤਿਹਾਰ ਦੇਣ ਵਾਲਾ ਡੈਸ਼ਬੋਰਡ ਪੂਰਵਦਰਸ਼ਨ',
    dashboardDesc: 'ਇੱਕ ਇਸ਼ਤਿਹਾਰ ਦੇਣ ਵਾਲੇ ਦੇ ਨਜ਼ਰੀਏ ਤੋਂ POVR ਵਿਗਿਆਪਨ ਪਲੇਟਫਾਰਮ ਦਾ ਅਨੁਭਵ ਕਰੋ. ਇਹ ਇੰਟਰਐਕਟਿਵ ਝਲਕ ਡੀਹਬ \'ਤੇ ਇਸ਼ਤਿਹਾਰ ਦੇਣ ਵਾਲੀਆਂ ਕੰਪਨੀਆਂ ਲਈ ਉਪਲਬਧ ਸਾਧਨਾਂ ਅਤੇ ਵਿਸ਼ਲੇਸ਼ਣ ਨੂੰ ਦਰਸਾਉਂਦੀ ਹੈ.',
