    paragraph2: 'DeHub DeHub ਪਲੇਟਫਾਰਮ \'ਤੇ DeHub ਟੋਕਨ ਦੀ ਕਿਸੇ ਵੀ ਵਰਤੋਂ ਨੂੰ ਰੱਦ ਕਰਨ ਦਾ ਅਧਿਕਾਰ ਰੱਖਦਾ ਹੈ. DeHub ਕਿਸੇ ਵੀ ਸਿੱਧੇ ਜਾਂ ਸਿੱਧੇ ਜਾਂ ਅਸਿੱਧੇ ਤੌਰ\' ਤੇ ਪੈਦਾ ਹੋਣ ਵਾਲੇ ਕਿਸੇ ਵੀ ਕਿਸਮ ਦੇ ਸਿੱਧੇ ਜਾਂ ਨਤੀਜੇ ਵਜੋਂ ਹੋਣ ਵਾਲੇ ਨੁਕਸਾਨ ਜਾਂ ਨੁਕਸਾਨ ਦੀ ਕਿਸੇ ਵੀ ਜ਼ਿੰਮੇਵਾਰੀ ਨੂੰ ਰੱਦ ਕਰਦਾ ਹੈਃ (i) ਪ੍ਰਦਾਨ ਕੀਤੀ ਗਈ ਕਿਸੇ ਵੀ ਜਾਣਕਾਰੀ \'ਤੇ ਨਿਰਭਰਤਾ, (ii) ਅਜਿਹੀ ਕਿਸੇ ਵੀ ਜਾਣਕਾਰੀ ਵਿਚ ਕੋਈ ਗਲਤੀ, ਕਮੀ ਜਾਂ ਗਲਤਤਾ; ਜਾਂ (iii) ਅਜਿਹੀ ਜਾਣਕਾਰੀ ਦੇ ਨਤੀਜੇ ਵਜੋਂ ਕੋਈ ਵੀ ਕਾਰਵਾਈ.',
    paragraph3: 'ਕ੍ਰਿਪਟੋਕਰੰਸੀ ਨਿਵੇਸ਼ ਵਿੱਚ ਮਹੱਤਵਪੂਰਨ ਜੋਖਮ ਸ਼ਾਮਲ ਹਨ।',
    paragraph4: 'ਪਿਛਲੀ ਕਾਰਗੁਜ਼ਾਰੀ ਭਵਿੱਖ ਦੇ ਨਤੀਜਿਆਂ ਦੀ ਗਰੰਟੀ ਨਹੀਂ ਹੈ।',
    paragraph5: 'ਉਪਭੋਗਤਾਵਾਂ ਨੂੰ ਹਿੱਸਾ ਲੈਣ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੀ ਖੋਜ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ।',
    paragraph6: 'DeHub ਟੀਮ ਕਿਸੇ ਵੀ ਨੁਕਸਾਨ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹੈ।',
    paragraph7: 'ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਤੁਹਾਡੇ ਆਪਣੇ ਜੋਖਮ \'ਤੇ ਹੈ।',
    paragraph8: 'ਨਿਯਮ ਅਧਿਕਾਰ ਖੇਤਰ ਅਨੁਸਾਰ ਵੱਖ-ਵੱਖ ਹੋ ਸਕਦੇ ਹਨ।',
    paragraph9: 'ਇਹ ਕਾਨੂੰਨੀ ਜਾਂ ਵਿੱਤੀ ਸਲਾਹ ਨਹੀਂ ਹੈ।',
    importantNotice: 'ਮਹੱਤਵਪੂਰਨ ਨੋਟਿਸ',
    disclaimer: 'ਬੇਦਾਅਵਾ',
    disclaimerText: 'ਇਹ ਦਸਤਾਵੇਜ਼ ਕਿਸੇ ਵੀ ਅਧਿਕਾਰ ਖੇਤਰ ਵਿੱਚ ਕਿਸੇ ਵੀ ਵਿਅਕਤੀ ਨੂੰ ਸਿਕਿਓਰਿਟੀਜ਼ ਦੀ ਖਰੀਦ ਜਾਂ ਵਿਕਰੀ ਲਈ ਕੋਈ ਪੇਸ਼ਕਸ਼ ਜਾਂ ਸੱਦਾ ਨਹੀਂ ਹੈ।',
