    heading: 'ਸੇਵਾ ਦੀਆਂ ਸ਼ਰਤਾਂ',
    paragraph1: 'DeHub ਸੇਵਾਵਾਂ ਤੱਕ ਪਹੁੰਚ ਕਰਕੇ ਜਾਂ ਵਰਤ ਕੇ, ਤੁਸੀਂ ਇਹਨਾਂ ਸ਼ਰਤਾਂ ਨਾਲ ਸਹਿਮਤ ਹੁੰਦੇ ਹੋ।',
    paragraph2: 'ਉਪਭੋਗਤਾਵਾਂ ਨੂੰ ਪਲੇਟਫਾਰਮ \'ਤੇ ਸਥਾਨਕ ਕਾਨੂੰਨਾਂ ਅਤੇ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ।',
    paragraph3: 'ਅਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਸੇਵਾ ਨੂੰ ਬਦਲਣ ਜਾਂ ਬੰਦ ਕਰਨ ਦਾ ਅਧਿਕਾਰ ਰੱਖਦੇ ਹਾਂ।',
    paragraph4: 'ਉਪਭੋਗਤਾ ਆਪਣੇ ਖਾਤੇ ਦੀ ਸੁਰੱਖਿਆ ਬਣਾਈ ਰੱਖਣ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਹਨ।',
    paragraph5: 'ਬੌਧਿਕ ਸੰਪੱਤੀ ਅਧਿਕਾਰ ਉਹਨਾਂ ਦੇ ਸਬੰਧਤ ਮਾਲਕਾਂ ਕੋਲ ਰਹਿੰਦੇ ਹਨ।',
    paragraph6: 'ਅਸੀਂ ਤੀਜੀ-ਧਿਰ ਸੇਵਾਵਾਂ ਜਾਂ ਸਮੱਗਰੀ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹਾਂ।',
    paragraph7: 'ਇਹ ਸ਼ਰਤਾਂ ਬਿਨਾਂ ਪੂਰਵ ਸੂਚਨਾ ਦੇ ਅੱਪਡੇਟ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ ਹਨ।',
    importantNotice: 'ਮਹੱਤਵਪੂਰਨ ਨੋਟਿਸ',
    disclaimer: 'ਬੇਦਾਅਵਾ',
    disclaimerText: 'ਇਹ ਸ਼ਰਤਾਂ DeHub ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ \'ਤੇ ਲਾਗੂ ਹੁੰਦੀਆਂ ਹਨ।',
    welcomeTitle: 'DeHub ਵਿੱਚ ਤੁਹਾਡਾ ਸਵਾਗਤ ਹੈ!',
    welcomeText: 'ਡੀਹਬ ਪਲੇਟਫਾਰਮ ਅਤੇ ਉਨ੍ਹਾਂ ਉਤਪਾਦਾਂ, ਸੇਵਾਵਾਂ ਅਤੇ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਦੀ ਵਰਤੋਂ ਕਰਨ ਲਈ ਤੁਹਾਡਾ ਧੰਨਵਾਦ ਜੋ ਅਸੀਂ ਤੁਹਾਨੂੰ ਪਲੇਟਫਾਰਮ ਦੇ ਹਿੱਸੇ ਵਜੋਂ ਉਪਲਬਧ ਕਰਾਉਂਦੇ ਹਾਂ (ਸਮੂਹਿਕ ਤੌਰ ਤੇ, "ਸੇਵਾ").',
    ourService: 'ਸਾਡੀ ਸੇਵਾ',
    ourServiceText1: 'ਸੇਵਾ ਤੁਹਾਨੂੰ ਪੂਰੀ ਤਰ੍ਹਾਂ ਵਿਕੇਂਦਰੀਕ੍ਰਿਤ ਵਾਤਾਵਰਣ ਵਿੱਚ ਸਮਗਰੀ ਨੂੰ ਖੋਜਣ, ਸਾਂਝਾ ਕਰਨ ਅਤੇ ਮੁਦਰੀਕਰਨ ਕਰਨ ਦੀ ਆਗਿਆ ਦਿੰਦੀ ਹੈ, ਲੋਕਾਂ ਨੂੰ ਵਿਸ਼ਵ ਭਰ ਵਿੱਚ ਦੂਜਿਆਂ ਨੂੰ ਜੋੜਨ, ਜਾਣਕਾਰੀ ਦੇਣ ਅਤੇ ਪ੍ਰੇਰਿਤ ਕਰਨ ਲਈ ਇੱਕ ਫੋਰਮ ਪ੍ਰਦਾਨ ਕਰਦੀ ਹੈ, ਅਤੇ ਕੇਂਦਰੀਕ੍ਰਿਤ ਪਾਬੰਦੀਆਂ ਤੋਂ ਬਿਨਾਂ ਅਸਲ ਸਮਗਰੀ ਸਿਰਜਣਹਾਰਾਂ ਲਈ ਇੱਕ ਵੰਡ ਪਲੇਟਫਾਰਮ ਵਜੋਂ ਕੰਮ ਕਰਦੀ ਹੈ. ਅਸੀਂ ਇੱਕ ਸੈਂਸਰਸ਼ਿਪ-ਰੋਧਕ ਪਲੇਟਫਾਰਮ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ ਜਿੱਥੇ ਕੋਈ ਵੀ ਕਾਰਪੋਰੇਟ ਨਿਯੰਤਰਣ ਦੀ ਬਜਾਏ ਕਮਿ communityਨਿਟੀ ਗਵਰਨੈਂਸ ਦੁਆਰਾ ਆਪਣੀ ਸਮਗਰੀ ਦਾ ਮੁਦਰੀਕਰਨ ਕਰ ਸਕਦਾ ਹੈ.',
    ourServiceText2: 'ਡੀਹਬ ਇੱਕ ਵਿਕੇਂਦਰੀਕ੍ਰਿਤ ਪ੍ਰੋਟੋਕੋਲ ਦੇ ਤੌਰ ਤੇ ਕੰਮ ਕਰਦਾ ਹੈ ਜਿੱਥੇ ਸਮਗਰੀ ਸੰਜਮ ਨੂੰ ਕਮਿ communityਨਿਟੀ ਗਵਰਨੈਂਸ ਦੁਆਰਾ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ, ਇਹ ਸੁਨਿਸ਼ਚਿਤ ਕਰਦੇ ਹੋਏ ਕਿ ਸਿਰਫ ਗੈਰਕਾਨੂੰਨੀ ਸਮਗਰੀ ਜਾਂ ਸਮਗਰੀ ਦੀ ਉਲੰਘਣਾ ਕਰਨ ਵਾਲੇ ਕਮਿ communityਨਿਟੀ ਦੁਆਰਾ ਪ੍ਰਵਾਨਿਤ ਦਿਸ਼ਾ ਨਿਰਦੇਸ਼ਾਂ ਨੂੰ ਸੀਮਤ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ.',
    softwareDevelopers: 'ਕੌਣ ਡੀਹਬ ਨੂੰ ਚਲਾਉਂਦਾ ਹੈ',
    softwareDevText1: 'ਡੀਹਬ ਇੱਕ ਸੁਤੰਤਰ ਡੀਏਓ ਹੈ. ਕੋਈ ਵੀ ਕੰਪਨੀ ਸੇਵਾ ਦੀ ਮਾਲਕੀ, ਸੰਚਾਲਨ ਜਾਂ ਨਿਯੰਤਰਣ ਨਹੀਂ ਕਰਦੀ. ਪ੍ਰੋਟੋਕੋਲ, ਪਲੇਟਫਾਰਮ ਅਤੇ ਖਜ਼ਾਨਾ ਡੀਹਬ ਟੋਕਨ ਧਾਰਕਾਂ ਦੁਆਰਾ ਆਨ-ਚੇਨ ਦੁਆਰਾ ਨਿਯੰਤਰਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਡੀਹਬ ਗਵਰਨੈਂਸ ਪ੍ਰੋਟੋਕੋਲ, ਜੋ ਕਿ ਲਾਈਵ ਹੈਃ ਪ੍ਰਸਤਾਵਾਂ ਨੂੰ ਐਪ ਵਿੱਚ ਉਭਾਰਿਆ ਅਤੇ ਵੋਟ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਨਤੀਜਾ ਵਾਤਾਵਰਣ ਪ੍ਰਣਾਲੀ ਨੂੰ ਬੰਨ੍ਹਦਾ ਹੈ. ਇਸ ਸਮਝੌਤੇ ਵਿੱਚ "ਡੀਹਬ," "ਅਸੀਂ," "ਸਾਨੂੰ" ਅਤੇ "ਸਾਡੇ" ਦਾ ਮਤਲਬ ਹੈ ਡੀਏਓ ਅਤੇ ਪ੍ਰੋਟੋਕੋਲ ਜੋ ਇਹ ਚਲਾਉਂਦਾ ਹੈ, ਇੱਕ ਕੰਪਨੀ ਨਹੀਂ.',
    softwareDevText2: 'ਵਿਕਾਸ ਡੀਏਓ ਦੁਆਰਾ ਲੱਗੇ ਸੁਤੰਤਰ ਯੋਗਦਾਨ ਪਾਉਣ ਵਾਲਿਆਂ ਅਤੇ ਸਟੂਡੀਓ ਦੁਆਰਾ ਕੀਤਾ ਜਾਂਦਾ ਹੈ. ਉਨ੍ਹਾਂ ਵਿਚੋਂ ਕੋਈ ਵੀ ਡੀਹਬ ਈਕੋਸਿਸਟਮ ਦਾ ਮਾਲਕ ਨਹੀਂ ਹੈ ਜਾਂ ਇਸ ਉੱਤੇ ਫੈਸਲਾ ਲੈਣ ਦੀ ਸ਼ਕਤੀ ਨਹੀਂ ਰੱਖਦਾ, ਅਤੇ ਉਨ੍ਹਾਂ ਵਿਚੋਂ ਕਿਸੇ ਨੂੰ ਵੀ ਸ਼ਾਸਨ ਦੀ ਵੋਟ ਦੁਆਰਾ ਬਦਲਿਆ ਜਾਂ ਹਟਾਇਆ ਜਾ ਸਕਦਾ ਹੈ. ਕੋਈ ਵੀ ਉਸ ਪ੍ਰਕਿਰਿਆ ਤੋਂ ਬਾਹਰ ਪ੍ਰੋਟੋਕੋਲ, ਟੋਕਨ ਜਾਂ ਇਹ ਸ਼ਰਤਾਂ ਨੂੰ ਬਦਲ ਨਹੀਂ ਸਕਦਾ.',
    whoMayUse: 'ਸੇਵਾ ਕੌਣ ਵਰਤ ਸਕਦਾ ਹੈ?',
    ageRequirements: 'ਉਮਰ ਦੀਆਂ ਲੋੜਾਂ',
    ageRequirementsText: 'ਤੁਸੀਂ ਸੇਵਾ ਦੀ ਵਰਤੋਂ ਸਿਰਫ ਤਾਂ ਹੀ ਕਰ ਸਕਦੇ ਹੋ ਜੇ ਤੁਸੀਂ ਘੱਟੋ ਘੱਟ 16 ਸਾਲ ਦੇ ਹੋ.',
    parentPermission: 'ਮਾਤਾ-ਪਿਤਾ ਜਾਂ ਸਰਪ੍ਰਸਤ ਦੁਆਰਾ ਆਗਿਆ',
    parentPermissionText: 'ਜੇ ਤੁਸੀਂ 18 ਸਾਲ ਤੋਂ ਘੱਟ ਉਮਰ ਦੇ ਹੋ, ਤਾਂ ਤੁਹਾਡੇ ਕੋਲ ਸੇਵਾ ਦੀ ਵਰਤੋਂ ਕਰਨ ਲਈ ਤੁਹਾਡੇ ਮਾਤਾ-ਪਿਤਾ ਜਾਂ ਕਾਨੂੰਨੀ ਸਰਪ੍ਰਸਤ ਦੀ ਆਗਿਆ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ. ਕਿਰਪਾ ਕਰਕੇ ਉਨ੍ਹਾਂ ਨੂੰ ਤੁਹਾਡੇ ਨਾਲ ਇਹ ਇਕਰਾਰਨਾਮਾ ਪੜ੍ਹਨ ਲਈ ਕਹੋ ।',
    businesses: 'ਕਾਰੋਬਾਰ',
