    purchaseLimits: 'ਖਰੀਦ ਸੀਮਾਵਾਂ',
    purchaseLimitsText: 'ਬੈਂਕ ਕਾਰਡ ਦੁਆਰਾ ਵੱਧ ਤੋਂ ਵੱਧ ਰੋਜ਼ਾਨਾ ਖਰੀਦ ਸੀਮਾ $ 500 ਡਾਲਰ ਦੇ ਬਰਾਬਰ ਹੈ. ਇਹ ਸੀਮਾ ਸੁਰੱਖਿਆ ਅਤੇ ਰੈਗੂਲੇਟਰੀ ਪਾਲਣਾ ਦੇ ਉਦੇਸ਼ਾਂ ਲਈ ਜਗ੍ਹਾ ਵਿੱਚ ਹੈ.',
    refundsPolicy: 'ਰਿਫੰਡ ਨੀਤੀ',
    refundsPolicyText: 'ਬਲਾਕਚੈਨ ਲੈਣ-ਦੇਣ ਦੇ ਅਟੱਲ ਸੁਭਾਅ ਦੇ ਕਾਰਨ, ਰਿਫੰਡ ਸਿਰਫ ਤਾਂ ਹੀ ਲਾਗੂ ਹੁੰਦੇ ਹਨ ਜੇ ਵਿਕਰੀ ਦਾ ਵਰਣਨ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ ਜਾਂ ਉਹ ਨਹੀਂ ਕਰਦਾ ਜੋ ਇਹ ਕਿਸੇ ਵੀ ਸਮਰੱਥਾ ਵਿੱਚ ਲਾਗੂ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ. ਸਾਰੀਆਂ ਟੋਕਨ ਖਰੀਦਾਂ ਅੰਤਮ ਹਨ ਅਤੇ ਉਲਟਾ ਨਹੀਂ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ, ਰੱਦ ਨਹੀਂ ਕੀਤੀਆਂ ਜਾਂ ਵਾਪਸ ਨਹੀਂ ਕੀਤੀਆਂ ਜਾ ਸਕਦੀਆਂ ਜਦੋਂ ਤੱਕ ਉਪਰੋਕਤ ਸ਼ਰਤਾਂ ਟੁੱਟੀਆਂ ਨਹੀਂ ਹੁੰਦੀਆਂ.',
    feesAndGas: 'ਫੀਸਾਂ ਅਤੇ ਗੈਸ ਦੀਆਂ ਕੀਮਤਾਂ',
    feesAndGasText: 'ਹਰ ਟੋਕਨ ਖਰੀਦ ਵਿੱਚ ਗੈਸ ਦੇ ਖਰਚਿਆਂ ਅਤੇ ਸੇਵਾ ਫੀਸਾਂ ਨੂੰ ਪੂਰਾ ਕਰਨ ਲਈ ਇੱਕ ਵਾਧੂ 1% ਫੀਸ ਸ਼ਾਮਲ ਹੁੰਦੀ ਹੈ. ਇਹ ਫੀਸਾਂ ਨੈਟਵਰਕ ਦੀਆਂ ਸਥਿਤੀਆਂ ਅਤੇ ਤੀਜੀ-ਪਾਰਟੀ ਸੇਵਾ ਪ੍ਰਦਾਤਾਵਾਂ ਦੇ ਅਧਾਰ ਤੇ ਵੱਖਰੀਆਂ ਹੋ ਸਕਦੀਆਂ ਹਨ.',
    fiatOnRamp: 'ਫਿਏਟ ਆਨ-ਰੈਂਪ ਸੇਵਾਵਾਂ',
    fiatOnRampText: 'ਅਸੀਂ ਟੋਕਨ ਖਰੀਦਦਾਰੀ ਦੀ ਸਹੂਲਤ ਲਈ ਤੀਜੀ-ਪਾਰਟੀ ਫਿਏਟ ਆਨ-ਰੈਂਪ ਸੇਵਾਵਾਂ ਤੱਕ ਪਹੁੰਚ ਪ੍ਰਦਾਨ ਕਰ ਸਕਦੇ ਹਾਂ. ਇਹ ਸੇਵਾਵਾਂ ਸੁਤੰਤਰ ਤੀਜੀ ਧਿਰ ਦੁਆਰਾ ਪ੍ਰਦਾਨ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਆਪਣੇ ਨਿਯਮਾਂ ਅਤੇ ਸ਼ਰਤਾਂ ਦੇ ਅਧੀਨ ਹੁੰਦੀਆਂ ਹਨ. ਅਸੀਂ ਇਸ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹਾਂਃ',
    fiatOnRampItem1: 'ਤੀਜੀ ਧਿਰ ਦੇ ਭੁਗਤਾਨ ਪ੍ਰੋਸੈਸਰਾਂ ਦੀ ਉਪਲਬਧਤਾ ਜਾਂ ਭਰੋਸੇਯੋਗਤਾ',
