    fiatOnRampItem4: 'ਤੁਹਾਡੇ ਅਧਿਕਾਰ ਖੇਤਰ ਵਿੱਚ ਸਥਾਨਕ ਭੁਗਤਾਨ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ',
    fiatOnRampItem5: 'ਭੁਗਤਾਨ ਨਾਲ ਜੁੜੇ ਮੁੱਦਿਆਂ ਲਈ ਗਾਹਕ ਸਹਾਇਤਾ (ਭੁਗਤਾਨ ਪ੍ਰਦਾਤਾ ਦੁਆਰਾ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ)',
    fiatOnRampNote: 'ਤੁਸੀਂ ਆਪਣੇ ਅਧਿਕਾਰ ਖੇਤਰ ਵਿੱਚ ਡਿਜੀਟਲ ਸੰਪਤੀ ਦੀ ਖਰੀਦ ਦੇ ਸੰਬੰਧ ਵਿੱਚ ਸਾਰੇ ਲਾਗੂ ਕਾਨੂੰਨਾਂ ਅਤੇ ਨਿਯਮਾਂ ਦੀ ਪਾਲਣਾ ਕਰਨ ਲਈ ਸਹਿਮਤ ਹੋ.',
