    decentralizedModerationItem2: 'ਸੰਜਮ ਨੀਤੀਗਤ ਫੈਸਲਿਆਂ ਲਈ ਪਾਰਦਰਸ਼ੀ, ਆਨ-ਚੇਨ ਵੋਟਿੰਗ ਪ੍ਰਕਿਰਿਆਵਾਂ',
    decentralizedModerationItem3: 'ਕਮਿ Communityਨਿਟੀ ਗਵਰਨੈਂਸ ਦੁਆਰਾ ਪ੍ਰਬੰਧਿਤ ਅਪੀਲ ਪ੍ਰਕਿਰਿਆ',
    decentralizedModerationItem4: 'ਨੀਤੀ ਇਕੋ ਇਕਾਈ ਦੀ ਬਜਾਏ ਸ਼ਾਸਨ ਦੁਆਰਾ ਨਿਰਧਾਰਤ ਕੀਤੀ ਜਾਂਦੀ ਹੈ; ਉਸ ਨੀਤੀ ਨੂੰ ਲਾਗੂ ਕਰਨਾ ਮਨੋਨੀਤ ਸੰਚਾਲਕਾਂ ਨੂੰ ਸੌਂਪਿਆ ਜਾਂਦਾ ਹੈ ਜੋ ਤੁਰੰਤ ਕੰਮ ਕਰਦੇ ਹਨ',
    designatedModerators: 'ਮਨੋਨੀਤ ਸੰਚਾਲਕ',
    designatedModeratorsText: 'ਕਮਿ Communityਨਿਟੀ ਦੁਆਰਾ ਚੁਣੇ ਗਏ ਪ੍ਰਸ਼ਾਸਕ ਅਤੇ ਚੋਟੀ ਦੇ ਦਰਜੇ ਦੇ ਬੈਜ ਧਾਰਕ ਸੌਂਪੇ ਗਏ ਸੰਜਮ ਦੇ ਅਧਿਕਾਰ ਰੱਖਦੇ ਹਨ. ਉਹ ਸਮਗਰੀ ਨੂੰ ਹਟਾ ਸਕਦੇ ਹਨ ਅਤੇ ਗਵਰਨੈਂਸ ਵੋਟ ਦੀ ਉਡੀਕ ਕੀਤੇ ਬਗੈਰ, ਤੁਰੰਤ ਦੁਰਵਿਵਹਾਰ ਕਰਨ ਵਾਲੇ ਖਾਤਿਆਂ ਨੂੰ ਮੁਅੱਤਲ ਕਰ ਸਕਦੇ ਹਨ ਜਾਂ ਬਾਹਰ ਕੱject ਸਕਦੇ ਹਨ, ਜਿੱਥੇ ਸਮਗਰੀ ਗੈਰਕਾਨੂੰਨੀ ਹੈ, ਕਮਿ communityਨਿਟੀ ਦਿਸ਼ਾ ਨਿਰਦੇਸ਼ਾਂ ਦੀ ਉਲੰਘਣਾ ਕਰਦੀ ਹੈ, ਜਾਂ ਉਪਭੋਗਤਾਵਾਂ ਨੂੰ ਨੁਕਸਾਨ ਪਹੁੰਚਾਉਣ ਦਾ ਜੋਖਮ ਪੇਸ਼ ਕਰਦੀ ਹੈ.',
    designatedModeratorsItem1: 'ਅਧਿਕਾਰਤ ਮੋਡਰੇਟਰ ਕੋਈ ਵੀ ਪੋਸਟ, ਕਮੈਂਟ, ਸਟਰੀਮ ਜਾਂ ਮੀਡੀਆ ਆਈਟਮ ਤੁਰੰਤ ਹੀ ਹਟਾ ਸਕਦੇ ਹਨ।',
    designatedModeratorsItem2: 'ਮਨੋਨੀਤ ਸੰਚਾਲਕ ਦੁਰਵਿਵਹਾਰ ਕਰਨ ਵਾਲੇ ਖਾਤਿਆਂ ਨੂੰ ਤੁਰੰਤ ਮੁਅੱਤਲ, ਸੀਮਤ ਜਾਂ ਪੱਕੇ ਤੌਰ \'ਤੇ ਬਾਹਰ ਕੱ ਸਕਦੇ ਹਨ',
