    commitmentTitle: 'ਵਿਕੇਂਦਰੀਕ੍ਰਿਤ ਗੋਪਨੀਯਤਾ ਪ੍ਰਤੀਬੱਧਤਾ',
    commitmentText: 'DeHub ਇੱਕ ਵਿਕੇਂਦਰੀਕ੍ਰਿਤ ਐਪਲੀਕੇਸ਼ਨ ਦੇ ਤੌਰ ਤੇ ਬਣਾਇਆ ਗਿਆ ਹੈ ਜੋ ਉਪਭੋਗਤਾ ਦੀ ਗੋਪਨੀਯਤਾ ਅਤੇ ਡੇਟਾ ਦੀ ਪ੍ਰਭੂਸੱਤਾ ਨੂੰ ਤਰਜੀਹ ਦਿੰਦਾ ਹੈ. ਇਹ ਗੋਪਨੀਯਤਾ ਨੀਤੀ ਦੱਸਦੀ ਹੈ ਕਿ ਅਸੀਂ ਆਪਣੇ ਵਿਕੇਂਦਰੀਕ੍ਰਿਤ ਵਾਤਾਵਰਣ ਪ੍ਰਣਾਲੀ ਵਿੱਚ ਜਾਣਕਾਰੀ ਨੂੰ ਕਿਵੇਂ ਸੰਭਾਲਦੇ ਹਾਂ.',
    corePrinciple: 'ਕੋਰ ਸਿਧਾਂਤਃ ਅਸੀਂ ਘੱਟੋ ਘੱਟ ਇੱਕ ਖਾਤੇ ਨੂੰ ਕੰਮ ਕਰਨ ਦੀ ਜ਼ਰੂਰਤ ਨੂੰ ਇਕੱਤਰ ਕਰਦੇ ਹਾਂ, ਅਸੀਂ ਇਸਨੂੰ ਕਦੇ ਨਹੀਂ ਵੇਚਦੇ, ਅਤੇ ਪਿਛਲੇ ਸਭ ਕੁਝ ਜੋ ਤੁਹਾਡੀ ਡਿਵਾਈਸ ਤੇ ਜਾਂ ਜਨਤਕ ਚੇਨ ਤੇ ਰਹਿੰਦਾ ਹੈ.',
