    doCollectItem2: 'ਤੁਹਾਡਾ ਖਾਤਾਃ ਉਪਭੋਗਤਾ ਨਾਮ, ਪ੍ਰੋਫਾਈਲ ਵੇਰਵੇ, ਅਵਤਾਰ, ਤੁਸੀਂ ਕਿਸ ਦੀ ਪਾਲਣਾ ਕਰਦੇ ਹੋ ਅਤੇ ਉਹ ਸੈਟਿੰਗਾਂ ਜੋ ਤੁਸੀਂ ਚੁਣਦੇ ਹੋ. ਕਈ ਪ੍ਰੋਫਾਈਲ ਇੱਕ ਡਿਵਾਈਸ ਤੇ ਬੈਠ ਸਕਦੇ ਹਨ, ਅਤੇ ਹਰ ਇੱਕ ਨੂੰ ਉਸੇ ਤਰ੍ਹਾਂ ਸਟੋਰ ਕੀਤਾ ਜਾਂਦਾ ਹੈ.',
    doCollectItem3: 'ਤੁਸੀਂ ਜੋ ਪ੍ਰਕਾਸ਼ਤ ਕਰਦੇ ਹੋ — ਪੋਸਟਾਂ, ਟਿੱਪਣੀਆਂ, ਅਪਲੋਡਸ ਅਤੇ ਉਨ੍ਹਾਂ ਦੇ ਆਲੇ ਦੁਆਲੇ ਦਾ ਮੈਟਾਡੇਟਾ — ਤਾਂ ਜੋ ਇਹ ਉਨ੍ਹਾਂ ਲੋਕਾਂ ਦੀ ਸੇਵਾ ਕੀਤੀ ਜਾ ਸਕੇ ਜਿਨ੍ਹਾਂ ਨੂੰ ਤੁਸੀਂ ਇਸ ਨੂੰ ਪ੍ਰਕਾਸ਼ਤ ਕੀਤਾ ਹੈ.',
    doCollectItem4: 'ਉਤਪਾਦ ਨੂੰ ਕੀ ਚਲਾਉਣ ਦੀ ਜ਼ਰੂਰਤ ਹੈਃ ਪੋਸਟਾਂ \'ਤੇ ਦ੍ਰਿਸ਼ਟੀਕੋਣ ਅਤੇ ਸ਼ਮੂਲੀਅਤ ਗਿਣਦੀ ਹੈ, ਅਤੇ ਇੱਕ ਡਿਵਾਈਸ ਪਛਾਣਕਰਤਾ ਜੋ ਇੱਕ ਸੈਸ਼ਨ ਨੂੰ ਗੁਣਕਾਰੀ ਰੱਖਦਾ ਹੈ ਤਾਂ ਜੋ ਤੁਸੀਂ ਆਪਣੇ ਖੁਦ ਦੇ ਕਿਰਿਆਸ਼ੀਲ ਸੈਸ਼ਨਾਂ ਨੂੰ ਵੇਖ ਅਤੇ ਰੱਦ ਕਰ ਸਕੋ.',
    doCollectItem5: 'ਕਿਸੇ ਵੀ ਚੀਜ਼ ਲਈ ਭੁਗਤਾਨ ਰਿਕਾਰਡ ਜੋ ਤੁਸੀਂ ਖਰੀਦਦੇ ਹੋ, ਭਾਵੇਂ ਇਹ ਸਟਰਾਈਪ ਜਾਂ ਆਨ-ਚੇਨ ਦੁਆਰਾ ਸੈਟਲ ਕੀਤਾ ਗਿਆ ਹੋਵੇ, ਲੇਖਾਕਾਰੀ ਅਤੇ ਵਿਵਾਦਾਂ ਲਈ ਰੱਖਿਆ ਗਿਆ. ਕਾਰਡ ਨੰਬਰ ਸਟਰਾਈਪ ਦੁਆਰਾ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਕਦੇ ਵੀ ਸਾਡੇ ਤੱਕ ਨਹੀਂ ਪਹੁੰਚਦਾ.',
