    contactItem2: 'ਸ਼ਾਸਨ ਵਿਚਾਰ ਵਟਾਂਦਰੇ ਵਿਚ ਹਿੱਸਾ ਲਓ',
    contactItem3: 'ਡੀ. ਏ. ਓ. ਰਾਹੀਂ ਪ੍ਰਸਤਾਵ ਜਮ੍ਹਾਂ ਕਰਵਾਓ',
    contactNote: 'ਇਸ ਗੋਪਨੀਯਤਾ ਨੀਤੀ ਨੂੰ ਕਮਿ communityਨਿਟੀ ਗਵਰਨੈਂਸ ਪ੍ਰਕਿਰਿਆਵਾਂ ਦੁਆਰਾ ਅਪਡੇਟ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ. ਪਦਾਰਥਕ ਤਬਦੀਲੀਆਂ ਨੂੰ ਸਾਡੇ ਅਧਿਕਾਰਤ ਚੈਨਲਾਂ ਦੁਆਰਾ ਦੱਸਿਆ ਜਾਵੇਗਾ.',
    importantNoticeText: 'ਡੀਹਬ ਇੱਕ ਵਿਕੇਂਦਰੀਕ੍ਰਿਤ ਪ੍ਰੋਟੋਕੋਲ ਦੇ ਤੌਰ ਤੇ ਕੰਮ ਕਰਦਾ ਹੈ. ਜਦੋਂ ਕਿ ਅਸੀਂ ਉਪਭੋਗਤਾ ਦੀ ਗੋਪਨੀਯਤਾ ਦੀ ਰੱਖਿਆ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਦੇ ਹਾਂ, ਵਿਕੇਂਦਰੀਕ੍ਰਿਤ ਸੁਭਾਅ ਦਾ ਅਰਥ ਹੈ ਕਿ ਪਰਸਪਰ ਪ੍ਰਭਾਵ ਜਨਤਕ ਬਲਾਕਚੈਨਾਂ ਤੇ ਦਿਖਾਈ ਦੇ ਸਕਦੇ ਹਨ. ਉਪਭੋਗਤਾ ਆਪਣੇ ਬਲਾਕਚੇਨ ਪਰਸਪਰ ਪ੍ਰਭਾਵ ਦੇ ਗੋਪਨੀਯਤਾ ਦੇ ਪ੍ਰਭਾਵਾਂ ਨੂੰ ਸਮਝਣ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਹਨ.',
    lastUpdatedDate: '29 ਸਤੰਬਰ 2026',
    doCollectItem1: 'ਪਛਾਣਕਰਤਾ ਜਿਸ ਨਾਲ ਤੁਸੀਂ ਸਾਈਨ ਇਨ ਕੀਤਾ ਹੈ — ਇੱਕ ਈਮੇਲ ਪਤਾ ਜਾਂ ਫੋਨ ਨੰਬਰ ਜੇ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਰੂਟਾਂ ਵਿੱਚੋਂ ਇੱਕ ਦੀ ਚੋਣ ਕੀਤੀ ਹੈ, ਪਛਾਣ ਗੂਗਲ, ਐਪਲ ਜਾਂ ਟੈਲੀਗ੍ਰਾਮ ਵਾਪਸ ਆਉਂਦੀ ਹੈ ਜੇ ਤੁਸੀਂ ਸਮਾਜਿਕ ਤੌਰ ਤੇ ਸਾਈਨ ਇਨ ਕੀਤਾ ਹੈ, ਜਾਂ ਇੱਕ ਪਾਸਕੀ ਦਾ ਜਨਤਕ ਪ੍ਰਮਾਣ ਪੱਤਰ. ਇੱਕ ਵਾਲਿਟ ਸਾਈਨ-ਇਨ ਸਾਨੂੰ ਤੁਹਾਡੇ ਜਨਤਕ ਪਤੇ ਤੋਂ ਇਲਾਵਾ ਕੁਝ ਨਹੀਂ ਦਿੰਦਾ.',
    doCollectItem7: 'ਉਹ ਚੀਜ਼ਾਂ ਜੋ ਤੁਸੀਂ ਚਾਲੂ ਕਰਨ ਲਈ ਚੁਣਦੇ ਹੋਃ ਟੈਕਸਟ ਨੋਟੀਫਿਕੇਸ਼ਨਾਂ ਲਈ ਇੱਕ ਫੋਨ ਨੰਬਰ, ਕੀ ਦੂਸਰੇ ਵੇਖਦੇ ਹਨ ਜਦੋਂ ਤੁਸੀਂ onlineਨਲਾਈਨ ਹੁੰਦੇ ਹੋ, ਅਤੇ ਬਾਹਰੀ ਸਮਾਜਿਕ ਖਾਤੇ ਜੋ ਤੁਸੀਂ ਮਲਟੀ-ਪੋਸਟਿੰਗ ਲਈ ਕਨੈਕਟ ਕਰਦੇ ਹੋ.',
    doCollectItem8: 'ਕਿਹੜੇ ਪੰਨਿਆਂ ਦਾ ਦੌਰਾ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਲੋਕ ਉਨ੍ਹਾਂ ਦੇ ਵਿਚਕਾਰ ਕਿਵੇਂ ਚਲਦੇ ਹਨ, ਤਾਂ ਜੋ ਅਸੀਂ ਵੇਖ ਸਕੀਏ ਕਿ ਕੀ ਕੰਮ ਕਰਦਾ ਹੈ. ਤੁਹਾਡੇ ਐਫੀਲੀਏਟ ਪੰਨਿਆਂ ਤੇ ਤੁਹਾਡੀਆਂ ਆਪਣੀਆਂ ਮੁਲਾਕਾਤਾਂ ਦੀ ਗਿਣਤੀ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ.',
    dontCollectItem6: 'ਤੁਹਾਡੇ ਕਾਰਡ ਦੇ ਵੇਰਵੇ, ਅਤੇ ਕਦੇ ਵੀ ਤੁਹਾਡੇ ਐਂਡ-ਟੂ-ਐਂਡ ਐਨਕ੍ਰਿਪਟਡ ਸਿੱਧੇ ਸੰਦੇਸ਼ਾਂ ਦਾ ਟੈਕਸਟ — ਉਹ ਸਾਡੇ ਲਈ ਪੜ੍ਹਨਯੋਗ ਨਹੀਂ ਹਨ. ਫੋਟੋਆਂ, ਵੀਡੀਓ ਅਤੇ ਸੰਦੇਸ਼ਾਂ ਵਿੱਚ ਫਾਈਲਾਂ, ਅਤੇ ਕਿਸੇ ਨੂੰ ਸੁਨੇਹੇ ਜਿਨ੍ਹਾਂ ਨੇ ਐਨਕ੍ਰਿਪਸ਼ਨ ਨੂੰ ਅਨਲੌਕ ਨਹੀਂ ਕੀਤਾ ਹੈ, ਅਜੇ ਤੱਕ ਅੰਤ ਤੋਂ ਅੰਤ ਵਿੱਚ ਐਨਕ੍ਰਿਪਟਡ ਨਹੀਂ ਹਨ.',
