    daoTitle: 'ਡੀਏਓ ਦੁਆਰਾ ਯੋਗਦਾਨ ਪਾਓ',
    daoBody: 'ਉਪਰੋਕਤ ਈਵੀਐਮ ਪਤਾ ਡੀਏਓ ਖਜ਼ਾਨਾ ਹੈ. ਐਪ ਤੋਂ ਇਸ \'ਤੇ ਡੀਐਚਬੀ ਭੇਜੋ ਅਤੇ ਤੁਹਾਡਾ ਯੋਗਦਾਨ ਪੂਲ ਦੇ ਤੁਹਾਡੇ ਹਿੱਸੇ ਵੱਲ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ, ਜੋ ਤੁਹਾਡੀ ਵੋਟ ਦਾ ਭਾਰ ਹੈ ਜਦੋਂ ਡੀਏਓ ਇਹ ਫੈਸਲਾ ਕਰਦਾ ਹੈ ਕਿ ਇਹ ਕਿਵੇਂ ਖਰਚਿਆ ਜਾਂਦਾ ਹੈ.',
