    subtitle: 'ਮੁਦਰਾ ਜੋ DeHub ਨੂੰ ਸ਼ਕਤੀ ਪ੍ਰਦਾਨ ਕਰਦੀ ਹੈ',
    intro: 'DeHub ਟੋਕਨ DeHub ਨੈਟਵਰਕ ਦੀ ਦੇਸੀ ਸਹੂਲਤ ਮੁਦਰਾ ਹਨ; ਡੀਐਚਬੀ ਉਨ੍ਹਾਂ ਦਾ ਟਿੱਕਰ ਪ੍ਰਤੀਕ ਹੈ. ਉਹ ਹਰ ਡੀ-ਐਪ ਦੇ ਪਾਰ ਖਾਤੇ ਦੀ ਇਕੋ ਇਕਾਈ ਹਨ — ਉਹ ਚੀਜ਼ ਜਿਸ ਨਾਲ ਤੁਸੀਂ ਟਿਪ ਕਰਦੇ ਹੋ, ਸਮਗਰੀ ਨੂੰ ਅਨਲੌਕ ਕਰਦੇ ਹੋ, ਵੇਖਣ ਅਤੇ ਬਣਾਉਣ ਲਈ ਕਮਾਉਂਦੇ ਹੋ, ਅਤੇ ਏਆਈ ਪੀੜ੍ਹੀ \'ਤੇ ਖਰਚ ਕਰਦੇ ਹੋ. ਕਿਉਂਕਿ ਉਹ ਆਨ-ਚੇਨ ਰਹਿੰਦੇ ਹਨ, ਵਾਤਾਵਰਣ ਪ੍ਰਣਾਲੀ ਵਿਚ ਮੁੱਲ ਦੀ ਹਰ ਲਹਿਰ ਜਨਤਕ ਤੌਰ\' ਤੇ ਪ੍ਰਮਾਣਿਤ ਹੁੰਦੀ ਹੈ ਨਾ ਕਿ ਇਕ ਪ੍ਰਾਈਵੇਟ ਲੈਜਰ ਵਿਚ ਬੈਠਣ ਦੀ ਬਜਾਏ ਤੁਹਾਨੂੰ ਸਾਡਾ ਸ਼ਬਦ ਲੈਣਾ ਪਏਗਾ.',
    howItWorksTitle: 'ਮੁਦਰਾ ਐਪ ਵਿੱਚ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀ ਹੈ',
    howItWorksDesc1: 'ਹਰ DeHub ਖਾਤੇ ਵਿੱਚ ਇੱਕ ਵਾਲਿਟ ਬਣਾਇਆ ਗਿਆ ਹੈ. ਤੁਸੀਂ ਇਸਨੂੰ ਸਾਡੇ ਸਟਰਾਈਪ ਗੇਟਵੇ ਦੁਆਰਾ ਇੱਕ ਕਾਰਡ ਨਾਲ ਫੰਡ ਦੇ ਸਕਦੇ ਹੋ, ਇਸਨੂੰ ਕਿਸੇ ਹੋਰ ਉਪਭੋਗਤਾ ਤੋਂ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦੇ ਹੋ, ਇਸਨੂੰ ਪਲੇਟਫਾਰਮ ਤੋਂ ਕਮਾ ਸਕਦੇ ਹੋ, ਜਾਂ ਇਸਨੂੰ ਕਿਸੇ ਸਵੈ-ਰੱਖਿਅਕ ਵਾਲਿਟ ਤੋਂ ਜਮ੍ਹਾ ਕਰ ਸਕਦੇ ਹੋ — ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਕੋਈ ਵੱਖਰਾ ਐਪ, ਐਕਸਟੈਂਸ਼ਨ ਜਾਂ ਬੀਜ ਵਾਕਾਂਸ਼ ਦੀ ਜ਼ਰੂਰਤ ਨਹੀਂ ਹੈ. ਬੈਲੇਂਸ, ਸੁਝਾਅ, ਅਨਲੌਕ ਅਤੇ ਇਨਾਮ ਸਾਰੇ ਡੀਹਬ ਟੋਕਨ ਵਿੱਚ ਸੈਟਲ ਹੁੰਦੇ ਹਨ, ਇਸ ਲਈ ਭੁਗਤਾਨ ਪ੍ਰੋਸੈਸਰ ਦੁਆਰਾ ਸਿੱਧੇ ਤੌਰ \'ਤੇ ਘੁੰਮਣ ਦੀ ਬਜਾਏ ਉਪਭੋਗਤਾਵਾਂ ਦੇ ਵਿਚਕਾਰ ਮੁੱਲ ਦੀਆਂ ਚਾਲਾਂ ਜੋ ਇੱਕ ਕੱਟ ਲੈਂਦੀਆਂ ਹਨ ਅਤੇ ਇੱਕ ਖਾਤਾ ਫ੍ਰੀਜ਼ ਕਰ ਸਕਦੀਆਂ ਹਨ.',
    howItWorksDesc2: 'ਹੋਲਡਿੰਗ ਅਤੇ ਸਟੈਕਿੰਗ ਇਹ ਵੀ ਬਦਲਦੀ ਹੈ ਕਿ ਐਪ ਤੁਹਾਡੇ ਲਈ ਕਿਵੇਂ ਵਿਵਹਾਰ ਕਰਦੀ ਹੈ. ਜਿੰਨੇ ਜ਼ਿਆਦਾ DeHub ਟੋਕਨ ਤੁਸੀਂ ਰੱਖਦੇ ਹੋ, ਤੁਹਾਡੀ ਪਲੇਟਫਾਰਮ ਫੀਸਾਂ ਨੂੰ ਘੱਟ ਕਰੋ ਅਤੇ ਜਿੰਨੀ ਜ਼ਿਆਦਾ ਸਮਰੱਥਾ ਤੁਸੀਂ ਅਨਲੌਕ ਕਰਦੇ ਹੋ — ਬੈਜ, ਤਸਦੀਕ, ਰੁਝਾਨ ਬੂਸਟ, ਕਲੱਬ ਟੀਅਰ ਅਤੇ ਪੂਰੇ ਨੈਟਵਰਕ ਵਿੱਚ ਵਧੇ ਹੋਏ ਅਧਿਕਾਰ. ਅਭਿਆਸ ਵਿੱਚ ਮੁਦਰਾ ਬੋਲਟ-ਆਨ ਨਹੀਂ ਹੈਃ ਇਹ ਇਜਾਜ਼ਤ ਪਰਤ, ਇਨਾਮ ਰੇਲ ਅਤੇ ਇਕੋ ਸਮੇਂ ਚੈਕਆਉਟ ਹੈ.',
