    profitShareTitle: 'ਲਾਭ ਸ਼ੇਅਰ',
    profitShareDesc1: 'DeHub ਇਸ ਲਈ ਤਿਆਰ ਕੀਤਾ ਗਿਆ ਹੈ ਤਾਂ ਜੋ ਨੈਟਵਰਕ ਦੀ ਵਰਤੋਂ ਕਰਨ ਵਾਲੇ ਲੋਕ ਇਸ ਦੇ ਮਾਲਕ ਹੋਣ. ਪ੍ਰੋਟੋਕੋਲ ਮਾਲੀਆ — ਪਲੇਟਫਾਰਮ ਫੀਸਾਂ, ਸਟੋਰ ਅਤੇ ਮਾਰਕੀਟਪਲੇਸ ਫੀਸਾਂ, ਇਸ਼ਤਿਹਾਰਬਾਜ਼ੀ, ਏਆਈ ਵਰਤੋਂ ਅਤੇ ਗੇਮ ਮਾਲੀਆ — ਉਹਨਾਂ ਧਾਰਕਾਂ ਨੂੰ ਵਾਪਸ ਵਗਦਾ ਹੈ ਜੋ ਹਿੱਸੇਦਾਰੀ ਕਰਦੇ ਹਨ, ਅਸਲ ਝਾੜ ਦੀ ਵੰਡ ਅਤੇ ਖਰੀਦ-ਬੈਕ ਦੇ ਰੂਪ ਵਿੱਚ ਨਾ ਕਿ ਤਾਜ਼ੇ ਮਿਨਟੇਡ ਸਪਲਾਈ ਦੀ ਬਜਾਏ. ਡੀਹਬ ਟੋਕਨ ਦਾ ਮਾਲਕ ਹੋਣਾ ਇਸ ਲਈ ਖੁਦ ਡੀਹਬ ਨੈਟਵਰਕ ਦੇ ਹਿੱਸੇ ਦੀ ਮਾਲਕੀ ਹੈ, ਨਾ ਕਿ ਸਿਰਫ ਖਰਚੇ ਦਾ ਸੰਤੁਲਨ.',
    profitShareDesc2: 'ਵੰਡਾਂ ਨੂੰ ਉਸ ਤੋਂ ਫੰਡ ਦਿੱਤਾ ਜਾਂਦਾ ਹੈ ਜੋ ਪ੍ਰੋਟੋਕੋਲ ਅਸਲ ਵਿੱਚ ਕਮਾਉਂਦਾ ਹੈ, ਪਰਿਵਰਤਨਸ਼ੀਲ ਅੰਤਰਾਲਾਂ ਤੇ, ਅਤੇ ਸਟੈਕ ਕੀਤੇ ਗਏ ਰਕਮ ਅਤੇ ਅਵਧੀ ਦੋਵਾਂ ਦੁਆਰਾ ਸਟੈਕਿੰਗ ਟੀਅਰਾਂ ਵਿੱਚ ਵੰਡਿਆ ਜਾਂਦਾ ਹੈ. ਲੰਬੀ ਵਚਨਬੱਧਤਾ ਹਰੇਕ ਵੰਡ ਦਾ ਵੱਡਾ ਹਿੱਸਾ ਕਮਾਉਂਦੀ ਹੈ. ਟੀਅਰ ਮਕੈਨਿਕਸ ਅਤੇ ਇਨਾਮ ਦੀ ਸਹੀ ਗਣਨਾ ਲਈ ਸਟੇਕ ਵੇਖੋ.',
    pegTitle: 'Pegged ਕੀਮਤ ਅਤੇ DEX ਸੂਚੀਕਰਨ',
    pegDesc1: 'DeHub ਟੋਕਨ ਇੱਕ ਉਪਯੋਗਤਾ ਟੋਕਨ ਹੈ. ਇਨ-ਐਪ ਦੇ ਉਦੇਸ਼ਾਂ ਲਈ ਇਹ ਇਸ ਸਮੇਂ ਪ੍ਰਤੀ ਟੋਕਨ $ 0.001 ਤੇ ਦਰਸਾਇਆ ਗਿਆ ਹੈ, ਜੋ ਕਿ ਤੁਸੀਂ ਫਿਏਟ ਗੇਟਵੇ ਦੁਆਰਾ ਖਰੀਦਣ ਵੇਲੇ ਵੇਖਦੇ ਹੋ ਅਤੇ ਇਨ-ਐਪ ਕੀਮਤ ਲਈ ਵਰਤੀ ਜਾਂਦੀ ਦਰ ਹੈ. ਉਹ ਪੀਈਜੀ ਇਨ-ਐਪ ਆਰਥਿਕਤਾ ਨੂੰ ਸਥਿਰ ਅਤੇ ਭਵਿੱਖਬਾਣੀਯੋਗ ਰੱਖਣ ਲਈ ਮੌਜੂਦ ਹੈ ਜਦੋਂ ਕਿ ਨੈਟਵਰਕ ਨੂੰ ਸਕੇਲ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ — ਇਹ ਇੱਕ ਅੰਦਰੂਨੀ ਲੇਖਾ ਦਰ ਹੈ, ਨਾ ਕਿ ਇੱਕ ਫਲੋਰ, ਗਰੰਟੀ ਜਾਂ ਭਵਿੱਖ ਦੇ ਮੁੱਲ ਦਾ ਵਾਅਦਾ.',
    pegDesc2: 'ਟੋਕਨ ਵਿਕੇਂਦਰੀਕ੍ਰਿਤ ਐਕਸਚੇਂਜਾਂ \'ਤੇ ਵਪਾਰ ਕਰਦਾ ਹੈ, ਤਰਲਤਾ ਪੂਲ ਉਸੇ 0.001 ਬੇਸ ਕੀਮਤ ਤੋਂ ਕਈ ਚੇਨਾਂ ਵਿਚ ਬੀਜਿਆ ਜਾਂਦਾ ਹੈ. ਖੁੱਲੇ ਬਾਜ਼ਾਰ ਵਿਚ ਕੀਮਤ ਵਪਾਰ ਦੁਆਰਾ ਨਿਰਧਾਰਤ ਕੀਤੀ ਜਾਂਦੀ ਹੈ — ਡੀਹਬ ਦੁਆਰਾ ਨਹੀਂ — ਜਿਸਦਾ ਅਰਥ ਹੈ ਡੀਹਬ ਟੋਕਨ ਕਿਸੇ ਵੀ ਸਮੇਂ ਇਨ-ਐਪ ਪੈਗ ਦੇ ਉੱਪਰ ਜਾਂ ਹੇਠਾਂ ਵਪਾਰ ਕਰ ਸਕਦੇ ਹਨ. ਡੀਹਬ ਡੀਈਐਕਸ\' ਤੇ ਆਪਣੀ ਅਧਿਕਾਰਤ ਤਰਲਤਾ ਬੀਜਦਾ ਹੈ ਤਾਂ ਜੋ ਹਰ ਲੈਣ-ਦੇਣ ਜਨਤਕ ਤੌਰ \'ਤੇ ਤਸਦੀਕ ਹੋਣ ਯੋਗ ਆਨ-ਚੇਨ ਰਹੇ.',
    disclaimer: 'ਬੇਦਾਅਵਾ',
    disclaimerNoApy: 'ਮਹੱਤਵਪੂਰਨਃ ਜਦੋਂ ਕਿ ਡੀਹਬ ਟੋਕਨ ਡੀਹਬ ਨੈਟਵਰਕ ਵਿੱਚ ਮਾਲਕੀ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ ਅਤੇ ਸਟੈਕਰਾਂ ਨੂੰ ਪ੍ਰੋਟੋਕੋਲ ਮੁਨਾਫਿਆਂ ਦੇ ਹਿੱਸੇ ਦਾ ਹੱਕਦਾਰ ਬਣਾਉਂਦਾ ਹੈ, ਇੱਥੇ ਕੋਈ ਨਿਰਧਾਰਤ ਏਪੀਵਾਈ ਨਹੀਂ ਹੈ, ਵਾਪਸੀ ਦੀ ਕੋਈ ਗਾਰੰਟੀਸ਼ੁਦਾ ਦਰ ਨਹੀਂ ਹੈ ਅਤੇ ਕਿਸੇ ਵੀ ਕਿਸਮ ਦੇ ਮੁਨਾਫੇ ਦੀ ਉਮੀਦ ਨਹੀਂ ਹੈ. ਸਾਰੇ ਵਿਤਰਣ ਪੂਰੀ ਤਰ੍ਹਾਂ ਨੈਟਵਰਕ ਦੀ ਕਾਰਗੁਜ਼ਾਰੀ ਤੇ ਨਿਰਭਰ ਕਰਦੇ ਹਨ ਅਤੇ ਪ੍ਰੋਟੋਕੋਲ ਅਸਲ ਵਿੱਚ ਇੱਕ ਨਿਰਧਾਰਤ ਅਵਧੀ ਵਿੱਚ ਪੈਦਾ ਕਰਦਾ ਹੈ. ਇਨਾਮ ਕਿਸੇ ਵੀ ਪਿਛਲੀ ਅਵਧੀ ਤੋਂ ਘੱਟ ਹੋ ਸਕਦੇ ਹਨ, ਅਤੇ ਜ਼ੀਰੋ ਹੋ ਸਕਦੇ ਹਨ. ਇਸ ਪੰਨੇ \'ਤੇ ਕੁਝ ਵੀ ਵਾਪਸੀ ਦਾ ਵਾਅਦਾ, ਪ੍ਰੋਜੈਕਸ਼ਨ ਜਾਂ ਪੇਸ਼ਕਸ਼ ਨਹੀਂ ਹੈ, ਅਤੇ ਇੱਥੇ ਕੁਝ ਵੀ ਵਿੱਤੀ ਸਲਾਹ ਨਹੀਂ ਹੈ.',
    disclaimerText: 'DeHub ਟੋਕਨ ਸਖਤੀ ਨਾਲ ਉਪਯੋਗਤਾ ਦੇ ਉਦੇਸ਼ਾਂ ਲਈ ਉਸੇ ਤਰੀਕੇ ਨਾਲ ਹਨ ਕਿ ਕੋਈ ਵੀ ਇਨ-ਗੇਮ ਜਾਂ ਇਨ-ਐਪ ਡਿਜੀਟਲ ਟੋਕਨ ਜਾਂ ਮੁਦਰਾਵਾਂ ਅਤੇ ਸਖਤੀ ਨਾਲ ਕੋਈ ਨਿਵੇਸ਼ ਨਹੀਂ. ਜਿਵੇਂ ਕਿ ਸਾਡਾ ਟੋਕਨ ਆਨ-ਚੇਨ ਰਹਿੰਦਾ ਹੈ, ਅਸੀਂ ਵਾਧੂ ਉਪਯੋਗਤਾ ਦੇ ਨਾਲ ਨਾਲ ਪ੍ਰਮਾਣਿਤ ਪਾਰਦਰਸ਼ਤਾ ਦੇ ਬੇਮਿਸਾਲ ਪੱਧਰਾਂ ਦੀ ਪੇਸ਼ਕਸ਼ ਕਰ ਸਕਦੇ ਹਾਂ. ਉਪਰੋਕਤ ਡੇਟਾ ਸਿਰਫ ਪਾਰਦਰਸ਼ਤਾ, ਵਿਦਿਅਕ ਅਤੇ ਜਾਣਕਾਰੀ ਦੇ ਉਦੇਸ਼ਾਂ ਲਈ ਇਕੱਤਰ ਕੀਤਾ ਗਿਆ ਹੈ. DeHub ਅਤੇ ਸਾਰੇ ਸਹਿਯੋਗੀ ਸਾਡੇ ਦੁਆਰਾ ਜਾਰੀ ਕੀਤੇ ਗਏ ਕਿਸੇ ਵੀ ਟੋਕਨ ਜਾਂ ਐਨਐਫਟੀ ਖਰੀਦਣ ਤੋਂ ਹੋਏ ਵਿੱਤੀ ਨੁਕਸਾਨ ਦੀ ਕੋਈ ਜ਼ਿੰਮੇਵਾਰੀ ਨਹੀਂ ਰੱਖਦੇ. ਬਾਜ਼ਾਰ ਬਹੁਤ ਉਤਰਾਅ-ਚੜ੍ਹਾਅ ਵਾਲੇ ਹਨ. ਤੁਹਾਨੂੰ ਇਹ ਵੀ ਅਜਿਹੇ ਯੋਗਤਾ ਅਸਫਲਤਾ, ਤਕਨੀਕੀ ਗਲਤੀ, ਹੈਕ ਅਤੇ ਇਸ \'ਤੇ ਦੇ ਤੌਰ ਤੇ ਕਿਸੇ ਵੀ ਅਚਾਨਕ ਗਲਤੀ ਦੇ ਕਾਰਨ ਆਪਣੇ ਸਾਰੇ ਪੈਸੇ ਨੂੰ ਗੁਆ ਸਕਦਾ ਹੈ. ਇਸ ਲਈ, ਤੁਹਾਨੂੰ ਸਿਰਫ ਉਹ ਖਰਚ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ ਜੋ ਤੁਸੀਂ ਗੁਆ ਸਕਦੇ ਹੋ.',
    useAiTitle: 'ਏਆਈ ਪੀੜ੍ਹੀ',
    useAiDesc: 'ਡੀਹਬ ਟੋਕਨ ਵਿਚ ਸਿਰਜਣਹਾਰ ਸਟੂਡੀਓ — ਚਿੱਤਰ, ਵੀਡੀਓ, ਆਡੀਓ ਅਤੇ 3 ਡੀ ਵਿਚ ਏਆਈ ਪੀੜ੍ਹੀ ਲਈ ਭੁਗਤਾਨ ਕਰੋ, ਹਰੇਕ ਨੌਕਰੀ ਚਲਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਹਵਾਲੇ ਕੀਤੀ ਗਈ ਕੀਮਤ \'ਤੇ, ਪ੍ਰਤੀ ਸਾਧਨ ਦੀ ਵੱਖਰੀ ਗਾਹਕੀ ਰੱਖਣ ਦੀ ਬਜਾਏ.',
