    step1Title: 'ਆਪਣਾ ਖਾਤਾ ਬਣਾਓ',
    step1Desc: 'Dehub. io ਖੋਲ੍ਹੋ ਅਤੇ ਸਾਈਨ ਇਨ \'ਤੇ ਟੈਪ ਕਰੋ । ਗੂਗਲ, ਐਪਲ, ਟੈਲੀਗ੍ਰਾਮ, ਈਮੇਲ, ਐਸਐਮਐਸ, ਪਾਸਕੀ ਜਾਂ ਵਾਲਿਟ ਦੀ ਚੋਣ ਕਰੋ. ਬੈਕਗ੍ਰਾਉਂਡ ਵਿੱਚ ਤੁਹਾਡੇ ਲਈ ਇੱਕ ਗੈਰ-ਰਖਵਾਲਾ ਵਾਲਿਟ ਬਣਾਇਆ ਗਿਆ ਹੈ — ਤੁਸੀਂ ਕੁੰਜੀਆਂ ਰੱਖਦੇ ਹੋ — ਅਤੇ ਗੈਸ ਸਪਾਂਸਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਇਸ ਲਈ ਤੁਹਾਡੇ ਸ਼ੁਰੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਫੰਡ ਦੇਣ ਲਈ ਕੁਝ ਵੀ ਨਹੀਂ ਹੁੰਦਾ.',
    step2Title: 'ਆਪਣੀ ਪ੍ਰੋਫਾਈਲ ਸੈਟ ਅਪ ਕਰੋ',
    step2Desc: 'ਸੈਟਿੰਗਾਂ ਵਿੱਚ → ਪ੍ਰੋਫਾਈਲ ਇੱਕ ਡਿਸਪਲੇਅ ਨਾਮ, ਉਪਭੋਗਤਾ ਨਾਮ, ਅਵਤਾਰ, ਕਵਰ ਚਿੱਤਰ ਅਤੇ ਬਾਇਓ ਸ਼ਾਮਲ ਕਰੋ, ਅਤੇ ਆਪਣੇ ਹੋਰ ਸੋਸ਼ਲਸ ਨੂੰ ਲਿੰਕ ਕਰੋ ਤਾਂ ਜੋ ਤੁਹਾਡੀ ਪ੍ਰੋਫਾਈਲ ਤੁਹਾਡੀ ਕੁੱਲ ਪਹੁੰਚ ਦਰਸਾਏ. ਸੈਟਿੰਗਾਂ ਦੀ → ਦਿੱਖ ਵਿੱਚ ਇੱਕ ਥੀਮ ਚੁਣੋ ਜਦੋਂ ਤੁਸੀਂ ਉਥੇ ਹੋ, ਅਤੇ ਵਿਕਲਪਿਕ ਗਾਈਡਡ ਵਾਕਥ੍ਰੂ ਲਓ ਜੇ ਤੁਸੀਂ ਆਲੇ ਦੁਆਲੇ ਦਿਖਾਉਣਾ ਚਾਹੁੰਦੇ ਹੋ.',
    step3Title: 'ਆਪਣੀ ਪਹਿਲੀ ਪੋਸਟ ਬਣਾਓ',
    step3Desc: 'ਟੈਪ ਕਰੋ ਬਣਾਓ. ਇੱਕ ਪੋਸਟ ਲਿਖੋ, ਚਿੱਤਰ, ਵੀਡੀਓ ਜਾਂ ਆਡੀਓ ਸ਼ਾਮਲ ਕਰੋ, ਲੰਬੇ ਫਾਰਮ ਲਿਖਣ ਲਈ ਆਰਟੀਕਲ ਤੇ ਸਵਿਚ ਕਰੋ, ਜਾਂ ਲਾਈਵ ਜਾਓ. ਪੋਸਟਿੰਗ ਰੋਜ਼ਾਨਾ ਭੱਤੇ ਤੱਕ ਮੁਫਤ ਹੈ — ਦਸ ਟੈਕਸਟ ਪੋਸਟਾਂ ਅਤੇ ਇੱਕ ਬੈਜ ਤੋਂ ਬਿਨਾਂ ਇੱਕ ਦਿਨ ਵਿੱਚ ਮੀਡੀਆ ਦੀ ਗੀਗਾਬਾਈਟ. ਚੇਨ \'ਤੇ ਇੱਕ ਪੋਸਟ ਮਿਨਟ ਕਰਨਾ ਵਿਕਲਪਿਕ ਹੈ ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ.',
    step4Title: 'ਆਪਣੇ ਦਰਸ਼ਕਾਂ ਤੋਂ ਕਮਾਓ',
    step4Desc: 'ਹਰ ਪੋਸਟ ਨੂੰ ਡੀਹਬ ਟੋਕਨ ਵਿੱਚ ਟਿਪ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ. ਉੱਥੋਂ ਤੁਸੀਂ ਗਾਹਕੀ ਵੇਚ ਸਕਦੇ ਹੋ, ਪੇ-ਪਰ-ਵਿਊ ਪੋਸਟਾਂ ਪ੍ਰਕਾਸ਼ਤ ਕਰ ਸਕਦੇ ਹੋ, ਸਿੱਧੇ ਸੰਦੇਸ਼ਾਂ ਲਈ ਘੱਟੋ ਘੱਟ ਟਿਪ ਸੈਟ ਕਰ ਸਕਦੇ ਹੋ, ਇੱਕ ਸਟੋਰ ਖੋਲ੍ਹ ਸਕਦੇ ਹੋ, ਬਾਉਂਟੀ ਪੋਸਟ ਕਰ ਸਕਦੇ ਹੋ ਅਤੇ ਉਹਨਾਂ ਲੋਕਾਂ ਤੋਂ ਕਮਾਈ ਕਰਨ ਲਈ ਆਪਣਾ ਐਫੀਲੀਏਟ ਲਿੰਕ ਸਾਂਝਾ ਕਰ ਸਕਦੇ ਹੋ ਜੋ ਤੁਸੀਂ ਲਿਆਉਂਦੇ ਹੋ.',
    step5Title: 'ਬੈਜ ਲਈ ਟੋਕਨ ਫੜੋ',
    step5Desc: 'ਡੀਹਬ ਟੋਕਨ ਨੂੰ ਫੜਨਾ ਜਾਂ ਸਟੈਕ ਕਰਨਾ ਇੱਕ ਬੈਜ ਕਮਾਉਂਦਾ ਹੈ, ਖਰਗੋਸ਼ ਤੋਂ ਲੈ ਕੇ ਮੇਗਾਲੋਡਨ ਤੱਕ. ਇੱਕ ਬੈਜ ਤੁਹਾਡੀਆਂ ਫੀਸਾਂ ਨੂੰ ਘਟਾਉਂਦਾ ਹੈ, ਤੁਹਾਡਾ ਪੋਸਟਿੰਗ ਭੱਤਾ ਵਧਾਉਂਦਾ ਹੈ, ਸੁਪਰਪਾਵਰਸ ਨੂੰ ਅਨਲੌਕ ਕਰਦਾ ਹੈ ਅਤੇ ਤੁਹਾਡੇ ਵਿਚਾਰਾਂ, ਪ੍ਰਤੀਕ੍ਰਿਆਵਾਂ ਅਤੇ ਵੋਟਾਂ ਵਿੱਚ ਭਾਰ ਜੋੜਦਾ ਹੈ.',
    step6Title: 'ਆਪਣਾ ਬਟੂਆ ਵਰਤੋ',
    step6Desc: 'ਤੁਹਾਡਾ ਬਟੂਆ ਕਈ ਚੇਨਾਂ ਵਿੱਚ ਡੀਹਬ ਟੋਕਨ ਅਤੇ ਹੋਰ ਕ੍ਰਿਪਟੂ ਰੱਖਦਾ ਹੈ. ਕਾਰਡ ਦੁਆਰਾ ਜਾਂ ਕ੍ਰਿਪਟੂ ਨਾਲ $ 0.50 ਤੋਂ ਟੋਕਨ ਖਰੀਦੋ, ਉਨ੍ਹਾਂ ਨੂੰ ਕਿਸੇ ਨੂੰ ਵੀ ਮੁਫਤ ਭੇਜੋ, ਡੀਹਬ ਐਕਸਚੇਂਜ \'ਤੇ ਵਪਾਰ ਕਰੋ, ਅਤੇ ਬੈਜ ਪੌੜੀ\' ਤੇ ਚੜ੍ਹਨ ਲਈ ਹਿੱਸੇਦਾਰੀ ਕਰੋ.',
    congratulations: '🎉 ਤੁਹਾਨੂੰ ਸੈੱਟਅੱਪ ਕੀਤਾ ਗਿਆ ਹੈ',
    congratulationsDesc: 'ਤੁਹਾਡੇ ਕੋਲ ਇੱਕ ਖਾਤਾ, ਇੱਕ ਪ੍ਰੋਫਾਈਲ ਅਤੇ ਇੱਕ ਪਹਿਲੀ ਪੋਸਟ ਹੈ. ਡੀਐਪ ਗਾਈਡ ਉਹ ਸਭ ਕੁਝ ਕਵਰ ਕਰਦੀ ਹੈ ਜੋ ਐਪ ਕਰ ਸਕਦੀ ਹੈ.',
